1620	void DispatcherNode::ScheduleTick() {
1621	  // 已受理的 ExecuteMission action 取消需在提前返回之前处理（10Hz 延迟 ≤100ms）
1622	  ProcessActionCancels();
1623	
1624	  // Task 5 Rule 2（Spec §5.2）：每 tick 先巡检受管小车链路。
1625	  // 离线 -> 挂起新派发（不消费 queue_start_requested_，恢复后自动继续）、
1626	  // 锁一律保留；在线但 state 陈旧 -> 仅软看门狗告警。受管清单为空时零开销跳过。
1627	  if (EnforceVda5050LinkGuard()) {
1628	    return;
1629	  }
1630	
1631	  if (!queue_ || queue_->empty()) {
1632	    return;
1633	  }
1634	  const std::size_t max_active = get_parameter("max_active_missions").as_int();
1635	  if (active_missions_.size() >= max_active) {
1636	    return;
1637	  }
1638	
1639	  // 执行模型：每台受管车同时只跑一条 /plan（多车则可并发多条）。
1640	  // 无可用执行槽位 -> 本 tick 不派发（任务留队，等某台车完成或状态变化后重试）。
1641	  if (!HasFreeVehicleSlot()) {
1642	    return;
1643	  }
1644	
1645	  // 地图版本门禁：配置了期望哈希且目录已加载时，
1646	  // 若目录哈希缺失，或与期望哈希不一致，均判定为环境地图与部署目录不匹配——暂停出队派发。
1647	  // 直接 return（不消费 queue_start_requested_），哈希恢复一致后派发自动继续。
1648	  map_version_valid_ = true;
1649	  if (!expected_map_hash_.empty() && catalog_reloader_ != nullptr &&
1650	      catalog_reloader_->loaded()) {
1651	    const auto& catalog = catalog_reloader_->catalog();
1652	    if (catalog.map_hash.empty() || catalog.map_hash != expected_map_hash_) {
1653	      map_version_valid_ = false;
1654	      RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 10000,
1655	                           "Map hash mismatch: expected %s, got %s, dispatching paused",
1656	                           expected_map_hash_.c_str(),
1657	                           catalog.map_hash.empty() ? "<missing>" : catalog.map_hash.c_str());
1658	      return;
1659	    }
1660	  }
1661	
1662	  // 行为树出队派发门控：runtime 树按"空闲 + 启动请求"给派发决策，
1663	  // 未请求启动时即使队列有任务也不出队（启动请求由提单/入队/结果链武装）。
1664	  amr_dispatcher_bt::MissionRuntimeBehaviorTreeInput runtime_input;
1665	  runtime_input.tick.mission_active = !HasFreeVehicleSlot();
1666	  runtime_input.tick.queue_start_requested = queue_start_requested_;
1667	  const auto runtime_result = amr_dispatcher_bt::TickMissionRuntimeBehaviorTree(runtime_input);
1668	  if (!runtime_result.success || !runtime_result.decision.start_queued_mission) {
1669	    return;
1670	  }
1671	  queue_start_requested_ = false;  // 启动请求被本次派发消费
1672	
1673	  // ---- A6 选车（PeekN 扫描 + 三态处理 + 队首阻塞规避）----
1674	  // 队首任务可能因"暂无合格车辆"而不可派；此时**不能**让整条队列堵死：
1675	  // 扫描前 N 个排队任务，挑第一个能选到车且能预留锁的。
1676	  const int64_t scan_depth_param =
1677	      std::max<int64_t>(1, get_parameter("assignment_scan_depth").as_int());
1678	  const std::size_t scan_depth = static_cast<std::size_t>(scan_depth_param);
1679	  const auto candidates = queue_->PeekN(scan_depth);
1680	  if (candidates.empty()) {
1681	    return;  // 队列任务全部暂停：与 PopNext 失败等价，本 tick 结束
1682	  }
1683	
1684	  struct Candidate {
1685	    amr_dispatcher_core::dispatcher::Mission mission;
1686	    std::string vehicle_id;
1687	    std::vector<std::string> route_locks;
1688	  };
1689	  std::vector<Candidate> ready;         // 选到车 + 预留成功的候选（按队列顺序）
1690	  bool saw_deferred = false;
1691	  bool saw_indeterminate = false;
1692	  std::string deferred_reason;
1693	  std::string indeterminate_reason;
1694	
1695	  for (const auto& candidate_mission : candidates) {
1696	    // 1) 选车（三态）
1697	    // 兼容红线：**legacy 单车模式**（既无 local_sim 受管车、也无 VDA 5050 受管车）
1698	    // 不走选车流程 —— 那里没有"车辆"概念，唯一的执行槽位是空串键
1699	    // （vehicle_current_mission_[""]），与改动前逐字等价。
1700	    // 若此处也调选车，request.vehicles 为空 -> 核心返回 kRejected
1701	    // ("no managed vehicles configured") -> 单车任务被永久判负（实测踩过）。
1702	    amr_dispatcher_core::fleet::VehicleAssignmentDecision decision;
1703	    if (HasAnyManagedVehicle()) {
1704	      decision = SelectVehicleForMission(candidate_mission);
1705	    } else {
1706	      decision.outcome = amr_dispatcher_core::fleet::AssignmentOutcome::kAssigned;
1707	      decision.strategy = "legacy_single_vehicle";
1708	    }
1709	    // 三态 -> 调度动作的映射写死在纯函数里（可单测，A7）：
1710	    // kDeferred 留队 / kIndeterminate 暂停自动分配 / kRejected 判负。
1711	    const auto dispatch_decision = DecideAssignmentDispatch(decision);
1712	    if (dispatch_decision.action == AssignmentDispatchAction::kStayQueued) {
1713	      saw_deferred = true;
1714	      deferred_reason = dispatch_decision.reason;
1715	      continue;  // 留队等待，下个 tick 重试
1716	    }
1717	    if (dispatch_decision.action == AssignmentDispatchAction::kPauseAutoAssignment) {
1718	      saw_indeterminate = true;
1719	      indeterminate_reason = dispatch_decision.reason;
1720	      continue;  // 状态不确定：暂停自动分配
1721	    }
1722	    if (dispatch_decision.action == AssignmentDispatchAction::kReject) {
1723	      // 永久不满足 -> 该单判负（不静默改派）
1724	      RCLCPP_WARN(get_logger(), "Queued mission %s rejected by vehicle selection: %s",
1725	                  candidate_mission.id.c_str(), dispatch_decision.reason.c_str());
1726	      if (queue_->Cancel(candidate_mission.id)) {
1727	        RejectedQueuedMission(candidate_mission, dispatch_decision.reason);
1728	      }
1729	      continue;
1730	    }
1731	    // 2) 预留路由锁（Peek→Reserve→Pop 原子链：预留成功才出队）
1732	    //    time_space 模式：预约**带时间窗**的路权（多车可错峰并行），
1733	    //    整条路径全有或全无；static 模式：静态排他锁（现网行为）。
1734	    std::vector<std::string> route_locks;
1735	    if (catalog_reloader_ != nullptr && catalog_reloader_->loaded()) {
1736	      route_locks = amr_dispatcher_core::workflow::PlanMissionRouteLocks(
1737	          catalog_reloader_->catalog(), candidate_mission.pickup_station,
1738	          candidate_mission.dropoff_station);
1739	    }
1740	    if (UseTimeSpaceMode()) {
1741	      // 时空窗模式：不占静态排他锁，改为预约时间窗。
1742	      std::vector<std::string> path_node_ids;
1743	      if (catalog_reloader_ != nullptr && catalog_reloader_->loaded() &&
1744	          !candidate_mission.pickup_station.empty()) {
1745	        const auto route_path = amr_dispatcher_core::catalog::FindRoutePath(
1746	            catalog_reloader_->catalog(), candidate_mission.pickup_station,
1747	            candidate_mission.dropoff_station);
1748	        if (route_path.has_value()) {
1749	          path_node_ids = *route_path;
1750	        }
1751	      }
1752	      std::string ts_message;
1753	      if (!ReserveTimeSpaceForMission(candidate_mission.id, path_node_ids, &ts_message)) {
1754	        RCLCPP_WARN(get_logger(),
1755	                    "Time-space reservation denied for queued mission %s: %s",
1756	                    candidate_mission.id.c_str(), ts_message.c_str());
1757	        pending_wait_[candidate_mission.id] = route_locks;
1758	        continue;  // 留队等待（换下一个候选）
1759	      }
1760	      // 时空模式下不占静态排他锁：route_locks 仅作记账用途
1761	      route_locks.clear();
1762	    }
1763	    if (!UseTimeSpaceMode() && !route_locks.empty() && reservation_table_) {
1764	      auto reserve = reservation_table_->Reserve(candidate_mission.id, route_locks);
1765	      if (!reserve.success) {
1766	        // 锁被占 -> 该单等锁（留队）；**不占用启动请求**，等锁释放时重试。
1767	        pending_wait_[candidate_mission.id] = route_locks;
1768	        RCLCPP_WARN(get_logger(), "Reservation denied for queued mission %s: %s",
1769	                    candidate_mission.id.c_str(), reserve.message.c_str());
1770	        if (event_pub_ && event_pub_->is_activated()) {
1771	          amr_dispatcher_interfaces::msg::MissionEvent msg;
1772	          msg.stamp = now();
1773	          msg.mission_id = candidate_mission.id;
1774	          msg.order_id = candidate_mission.order_id;
1775	          msg.event = "reservation_denied";
1776	          msg.from_state = "PENDING";
1777	          msg.to_state = "PENDING";  // 任务留在队列，状态不变
1778	          msg.reason = reserve.message;
1779	          event_pub_->publish(msg);
1780	        }
1781	        if (event_log_) {
1782	          amr_dispatcher_core::dispatcher::MissionEvent evt;
1783	          evt.stamp = "now";
1784	          evt.mission_id = candidate_mission.id;
1785	          evt.event = "reservation_denied";
1786	          evt.message = reserve.message;
1787	          event_log_->Append(evt);
1788	        }
1789	        continue;  // 换下一个候选（队首阻塞规避）
1790	      }
1791	      mission_reserved_at_[candidate_mission.id] = std::chrono::steady_clock::now();
1792	    }
1793	    pending_wait_.erase(candidate_mission.id);
1794	    Candidate ready_candidate;
1795	    ready_candidate.mission = candidate_mission;
1796	    ready_candidate.vehicle_id = decision.vehicle_id;
1797	    ready_candidate.route_locks = std::move(route_locks);
1798	    ready.push_back(std::move(ready_candidate));
1799	    break;  // 本 tick 只派一个（保持"一次一个"的节奏与可观测性）
1800	  }
1801	
1802	  if (ready.empty()) {
1803	    if (saw_indeterminate) {
1804	      // 状态不确定 -> 暂停自动分配（不消费启动请求，等状态恢复自动继续）
1805	      auto_assignment_paused_ = true;
1806	      RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 5000,
1807	                           "Auto vehicle assignment paused: %s", indeterminate_reason.c_str());
1808	      ReArmQueueStartRequest();
1809	    } else if (saw_deferred) {
1810	      RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 5000,
1811	                           "Vehicle assignment deferred, mission stays queued: %s",
1812	                           deferred_reason.c_str());
1813	      ReArmQueueStartRequest();  // 留队等待，下个 tick 重试
1814	    }
1815	    return;
1816	  }
1817	  auto_assignment_paused_ = false;
1818	
1819	  const std::string candidate_id = ready.front().mission.id;
1820	  const std::string candidate_order_id = ready.front().mission.order_id;
1821	  std::vector<std::string> route_locks = std::move(ready.front().route_locks);
1822	  const std::string dispatch_vehicle_id = ready.front().vehicle_id;
1823	  // 执行后端（评审 P0.1）：VDA 5050 车自带控制器，不走本地 /plan 运动链。
1824	  const bool is_vda5050_dispatch =
1825	      std::find(vda5050_vehicle_ids_.begin(), vda5050_vehicle_ids_.end(),
1826	                dispatch_vehicle_id) != vda5050_vehicle_ids_.end();
1827	
1828	  auto pop = queue_->PopById(candidate_id);
1829	  if (!pop.success || !pop.mission) {
1830	    // 出队失败（任务已被取消/暂停）：释放刚预留的锁，保持原子性
1831	    if (reservation_table_) {
1832	      reservation_table_->Release(candidate_id);
1833	    }
1834	    ReArmQueueStartRequest();
1835	    return;
1836	  }
1837	
1838	  amr_dispatcher_core::dispatcher::Mission m = *pop.mission;
1839	  m.state = amr_dispatcher_core::dispatcher::MissionState::kActive;
1840	  m.assigned_vehicle_id = dispatch_vehicle_id;  // 落定承接车辆（审计用）
1841	
1842	  // 解析起终点：无 pickup 时用车辆当前位姿作起点；站点缺失或目录未加载直接判负
1843	  const amr_dispatcher_core::catalog::Station* from_st = nullptr;
1844	  const amr_dispatcher_core::catalog::Station* to_st = nullptr;
1845	  const bool catalog_loaded =
1846	      catalog_reloader_ != nullptr && catalog_reloader_->loaded();
1847	  if (catalog_loaded) {
1848	    const auto& catalog = catalog_reloader_->catalog();
1849	    if (!m.pickup_station.empty()) {
1850	      from_st = amr_dispatcher_core::catalog::FindStation(catalog, m.pickup_station);
1851	    }
1852	    if (!m.dropoff_station.empty()) {
1853	      to_st = amr_dispatcher_core::catalog::FindStation(catalog, m.dropoff_station);
1854	    }
1855	  }
1856	  if (m.dropoff_station.empty() || !to_st) {
1857	    RCLCPP_WARN(get_logger(), "Mission %s has no resolvable dropoff station (%s, catalog_loaded=%d), failing",
1858	                m.id.c_str(), m.dropoff_station.c_str(), catalog_loaded);
1859	    if (event_pub_ && event_pub_->is_activated()) {
1860	      amr_dispatcher_interfaces::msg::MissionEvent msg;
1861	      msg.stamp = now();
1862	      msg.mission_id = m.id;
1863	      msg.order_id = m.order_id;
1864	      msg.event = "plan_failed";
1865	      msg.to_state = "FAILED";
1866	      msg.reason = "unknown dropoff station: " + m.dropoff_station;
1867	      event_pub_->publish(msg);
1868	    }
1869	    // 本单已出队但被判负丢弃：Peek 阶段预留的路由锁须就地释放
1870	    //（任务不进 active_missions_，走不到 Complete/Fail 的终态清理）
1871	    if (reservation_table_) {
1872	      reservation_table_->Release(m.id);
1873	    }
1874	    ForgetMissionDispatchState(m.id);
1875	    // ExecuteMission goal 须就地 abort：该分支不经 Complete/Fail，不收口则
1876	    // action 客户端永久悬挂、handle 残留在 execute_goal_handles_（终审 F8）
1877	    //（mission_dispatch_time_ 此刻尚未写入，无需额外遗忘）
1878	    FinishExecuteGoal(m.id, ExecuteFinish::kAbort,
1879	                      "unknown dropoff station: " + m.dropoff_station, 1);
1880	    ReArmQueueStartRequest();  // 本单丢弃后，队列中其余任务仍需能被派发
1881	    return;
1882	  }
1883	
1884	  // 预留成功：持有锁列表（逗号连接）回填任务，供死锁检测长持锁启发式取证
1885	  if (!route_locks.empty()) {
1886	    std::string joined_locks;
1887	    for (const auto& lock_id : route_locks) {
1888	      if (!joined_locks.empty()) {
1889	        joined_locks += ",";
1890	      }
1891	      joined_locks += lock_id;
1892	    }
1893	    m.reservation_id = joined_locks;
1894	  }
1895	
1896	  active_missions_[m.id] = m;
1897	  mission_last_progress_[m.id] = std::chrono::steady_clock::now();
1898	
1899	  // Task 5：存档本单行驶路径（travel order），供小车 state 逐段解锁回推身后锁。
1900	  // Peek 阶段的 PlanMissionRouteLocks 只产出锁列表（BuildLockIds 顺序非行驶序），
1901	  // 行驶序须在此按同一目录快照经 FindRoutePath 重算存档；无路径则该单不参与动态解锁。
1902	  if (catalog_loaded && !m.pickup_station.empty()) {
1903	    const auto route_path = amr_dispatcher_core::catalog::FindRoutePath(
1904	        catalog_reloader_->catalog(), m.pickup_station, m.dropoff_station);
1905	    if (route_path.has_value()) {
1906	      mission_route_paths_[m.id] = *route_path;
1907	    } else {
1908	      RCLCPP_WARN(get_logger(),
1909	                  "Mission %s: no topology path archived; dynamic unlock disabled for this mission",
1910	                  m.id.c_str());
1911	    }
1912	  }
1913	
1914	  // Task 6（Task 5 评审 I2）：受管 VDA 5050 车辆的订单发布——存档路径 + 本单持锁
1915	  // 构建 VehicleOrder 并经 /fleet/{vid}/send_order 下发（网关转 MQTT order 话题）。
1916	  // 失败不判负任务：plan/action 执行链照旧，订单缺口仅告警（发布端尽力而为）。
1917	  // 承接车辆由选车决策给出（A6），不再用 round-robin 盲选。
1918	  PublishVda5050Order(m.id, dispatch_vehicle_id);
1919	
1920	  // 生成并发布路径：path_tracker 订阅 /plan 后开始输出 /cmd_vel_raw
1921	  amr_dispatcher_core::Pose2D start;
1922	  if (from_st) {
1923	    start = {from_st->x, from_st->y, from_st->yaw};
1924	  } else if (has_odom_) {
1925	    start = {current_pose_.x, current_pose_.y, current_pose_.yaw};
1926	  }
1927	  const amr_dispatcher_core::Pose2D goal{to_st->x, to_st->y, to_st->yaw};
1928	
1929	  const auto waypoints = planner_ ? planner_->Plan(start, goal) : std::vector<amr_dispatcher_core::Pose2D>{};
1930	  const auto plan_pub = PlanPublisherForVehicle(dispatch_vehicle_id);
1931	  if (waypoints.empty() || !plan_pub || !plan_pub->is_activated()) {
1932	    FailMission(m.id, "planner returned empty path");
1933	    return;
1934	  }
1935	
1936	  // 记录派发起点：ExecuteMission feedback 按此直线距离折算 percent_complete
1937	  mission_dispatch_start_[m.id] = {start.x, start.y, start.theta};
1938	  // 派发时刻：ExecuteMission result.total_duration_sec 由此计时
1939	  mission_dispatch_time_[m.id] = std::chrono::steady_clock::now();
1940	
1941	  // 执行后端：action 模式不发 /plan，改为向 /navigate_sequence 发单点 goal
1942	  //（waypoint=规划终点，station_names=[dropoff]）；默认 plan 模式以下路径不变。
1943	  if (navigation_backend_ == "action") {
1944	    if (!nav_client_) {
1945	      FailMission(m.id, "navigate_sequence client not configured");
1946	      return;
1947	    }
1948	    if (!nav_client_->action_server_is_ready()) {
1949	      FailMission(m.id, "navigate_sequence action server not available (is bridge running?)");
1950	      return;
1951	    }
1952	    const auto& wp = waypoints.back();
1953	    NavigateSequence::Goal nav_goal;
1954	    geometry_msgs::msg::PoseStamped ps;
1955	    ps.header.stamp = now();
1956	    ps.header.frame_id = "map";
1957	    ps.pose.position.x = wp.x;
1958	    ps.pose.position.y = wp.y;
1959	    ps.pose.orientation.z = std::sin(wp.theta / 2.0);
1960	    ps.pose.orientation.w = std::cos(wp.theta / 2.0);
1961	    nav_goal.waypoints.push_back(ps);
1962	    nav_goal.station_names.push_back(m.dropoff_station);
1963	    nav_goal.loop = false;
1964	
1965	    rclcpp_action::Client<NavigateSequence>::SendGoalOptions opts;
1966	    const std::string mission_id = m.id;
1967	    opts.goal_response_callback = [this, mission_id](const GoalHandleNavigate::SharedPtr& gh) {
1968	      NavGoalResponseCb(mission_id, gh);
1969	    };
1970	    opts.feedback_callback = [this, mission_id](const GoalHandleNavigate::SharedPtr& gh,
1971	                                                const std::shared_ptr<const NavigateSequence::Feedback> fb) {
1972	      NavFeedbackCb(mission_id, gh, fb);
1973	    };
1974	    opts.result_callback = [this, mission_id](const GoalHandleNavigate::WrappedResult& result) {
1975	      NavResultCb(mission_id, result);
1976	    };
1977	    // 先占住单车执行槽位再发 goal，避免 goal 响应回调前的派发空窗
1978	    pending_nav_mission_id_ = m.id;
1979	    AssignTrackingSlot(m.id, dispatch_vehicle_id);
1980	    nav_client_->async_send_goal(nav_goal, opts);
1981	
1982	    RCLCPP_INFO(get_logger(),
1983	                "Dispatched mission via NavigateSequence: %s (order=%s, type=%s, prio=%d, %s->%s)",
1984	                m.id.c_str(), m.order_id.c_str(), m.type.c_str(), m.priority,
1985	                m.pickup_station.c_str(), m.dropoff_station.c_str());
1986	
1987	    if (event_pub_ && event_pub_->is_activated()) {
1988	      amr_dispatcher_interfaces::msg::MissionEvent msg;
1989	      msg.stamp = now();
1990	      msg.mission_id = m.id;
1991	      msg.order_id = m.order_id;
1992	      msg.event = "active";
1993	      msg.from_state = "PENDING";
1994	      msg.to_state = "ACTIVE";
1995	      msg.reason = "dispatched by scheduler";
1996	      event_pub_->publish(msg);
1997	    }
1998	    return;
1999	  }
2000	
2001	  nav_msgs::msg::Path path_msg;
2002	  path_msg.header.stamp = now();
2003	  path_msg.header.frame_id = "map";
2004	  path_msg.poses.reserve(waypoints.size());
2005	  for (const auto& wp : waypoints) {
2006	    geometry_msgs::msg::PoseStamped ps;
2007	    ps.header = path_msg.header;
2008	    ps.pose.position.x = wp.x;
2009	    ps.pose.position.y = wp.y;
2010	    ps.pose.orientation.z = std::sin(wp.theta / 2.0);
2011	    ps.pose.orientation.w = std::cos(wp.theta / 2.0);
2012	    path_msg.poses.push_back(ps);
2013	  }
2014	  // 执行后端分离（评审 P0.1）：VDA 5050 车自带控制器，**不发本地 /plan**
2015	  //（否则外部车会同时收到一条"本地折线"与一条 MQTT order，两套运动源互相打架），
2016	  // 也不占用本地 /plan 执行槽位；其"执行中"由订单状态判定（lastNodeId 推进），
2017	  // 完成判定见 Vda5050StateCb。
2018	  if (!is_vda5050_dispatch) {
2019	    PublishPlanForVehicle(dispatch_vehicle_id, path_msg);
2020	    AssignTrackingSlot(m.id, dispatch_vehicle_id);
2021	  }
2022	  RCLCPP_INFO(get_logger(), "Dispatched mission: %s (order=%s, type=%s, prio=%d, %s->%s, %zu waypoints, vehicle=%s)",
2023	              m.id.c_str(), m.order_id.c_str(), m.type.c_str(), m.priority,
2024	              m.pickup_station.c_str(), m.dropoff_station.c_str(), waypoints.size(),
2025	              dispatch_vehicle_id.empty() ? "<unassigned>" : dispatch_vehicle_id.c_str());
2026	
2027	  // A5/A7：多车并发 —— 本单已占用一台车，但**其它车可能仍空闲**。
2028	  // 重新武装启动请求：下个 tick 若还有空闲槽位，队列中的下一单会被派给另一台车，
2029	  // 从而形成真并发（否则第二单要等第一单完成才派发，"两车同时在跑"根本无从发生）。
2030	  // 单车场景行为不变：此时唯一槽位已被本单占满，ScheduleTick 的
2031	  // HasFreeVehicleSlot() 门控会直接返回（兼容红线：单车路径逐字不变）。
2032	  ReArmQueueStartRequest();
2033	
2034	  if (event_pub_ && event_pub_->is_activated()) {
2035	    amr_dispatcher_interfaces::msg::MissionEvent msg;
2036	    msg.stamp = now();
2037	    msg.mission_id = m.id;
2038	    msg.order_id = m.order_id;
2039	    msg.event = "active";
2040	    msg.from_state = "PENDING";
2041	    msg.to_state = "ACTIVE";
2042	    msg.reason = "dispatched by scheduler";
2043	    event_pub_->publish(msg);
2044	  }
2045	}
