     9	namespace amr_dispatcher_ros {
    10	
    11	// NavigateSequence 航点位姿构建（B3）：
    12	// 从 HandleAccepted 中抽出的纯逻辑，可脱离 rclcpp 单测。
    13	// 规则：
    14	//   - 单航点：保留客户端给的原始四元数（不得用 atan2 覆盖）；
    15	//   - 多航点：按相邻点 atan2 推航向并重写 orientation（与原实现一致）。
    16	inline std::vector<geometry_msgs::msg::PoseStamped> BuildNavPoses(
    17	    const std::vector<geometry_msgs::msg::PoseStamped>& waypoints,
    18	    const std::string& frame_id = "map") {
    19	  std::vector<geometry_msgs::msg::PoseStamped> out;
    20	  const std::size_t n = waypoints.size();
    21	  out.reserve(n);
    22	  for (std::size_t i = 0; i < n; ++i) {
    23	    geometry_msgs::msg::PoseStamped ps;
    24	    ps.header.frame_id = frame_id;
    25	    ps.pose = waypoints[i].pose;
    26	    if (n > 1) {
    27	      // 末点沿用倒数第二段朝向（与原实现语义一致）
    28	      const auto& a = (i + 1 < n) ? waypoints[i] : waypoints[i - 1];
    29	      const auto& b = (i + 1 < n) ? waypoints[i + 1] : waypoints[i];
    30	      const double yaw = std::atan2(b.pose.position.y - a.pose.position.y,
    31	                                    b.pose.position.x - a.pose.position.x);
    32	      ps.pose.orientation.x = 0.0;
    33	      ps.pose.orientation.y = 0.0;
    34	      ps.pose.orientation.z = std::sin(yaw / 2.0);
    35	      ps.pose.orientation.w = std::cos(yaw / 2.0);
    36	    }
    37	    out.push_back(ps);
    38	  }
    39	  return out;
    40	}
    41	
    42	}  // namespace amr_dispatcher_ros
