    14	//   - 上次 /cmd_vel_raw 距 now 超过 heartbeat_timeout -> 周期帧零速（上游失联兜底）；
    15	//   - 否则重发最近一次门控裁决值；从未收到过 raw 指令（has_decision=false）时不发。
    16	enum class PeriodicPublishKind { kSkip, kZero, kDecision };
    17	
    18	struct PeriodicPublishInput {
    19	  bool estop_or_fault = false;
    20	  bool bumper = false;
    21	  bool decision_critical = false;
    22	  bool has_decision = false;              // 是否已收到过至少一条 /cmd_vel_raw
    23	  bool has_last_raw_stamp = false;        // last_raw_stamp 是否有效
    24	  std::chrono::steady_clock::time_point last_raw_stamp{};
    25	  std::chrono::steady_clock::time_point now{};
    26	  std::chrono::milliseconds heartbeat_timeout{500};
    27	  double last_linear_x_mps = 0.0;
    28	  double last_linear_y_mps = 0.0;
    29	  double last_angular_z_radps = 0.0;
    30	};
    31	
    32	struct PeriodicPublishOutput {
    33	  PeriodicPublishKind kind = PeriodicPublishKind::kSkip;
    34	  double linear_x_mps = 0.0;
    35	  double linear_y_mps = 0.0;
    36	  double angular_z_radps = 0.0;
    37	  std::string reason;
    38	};
    39	
    40	inline PeriodicPublishOutput ComputePeriodicPublish(const PeriodicPublishInput& in) {
    41	  PeriodicPublishOutput out;
    42	
    43	  // 阻止源激活：estop/auto_fault/bumper 或门控裁决 critical，周期帧一律零速。
    44	  if (in.estop_or_fault || in.bumper || in.decision_critical) {
    45	    out.kind = PeriodicPublishKind::kZero;
    46	    out.reason = in.estop_or_fault   ? "estop"
    47	                 : in.bumper         ? "bumper"
    48	                                     : "critical_event";
    49	    return out;
    50	  }
    51	
    52	  // 上游失联兜底：已经收到过 raw 指令且距上次接收超过超时阈值 -> 零速。
    53	  //（从未收到 raw 的系统视为"尚未开始运动"，不持续发零速，避免空转告警）
    54	  if (in.has_last_raw_stamp &&
    55	      in.now - in.last_raw_stamp > in.heartbeat_timeout) {
    56	    out.kind = PeriodicPublishKind::kZero;
    57	    out.reason = "cmd_vel_raw_stale";
    58	    return out;
    59	  }
    60	
    61	  // 正常路径：重放最近一次裁决结果；尚未裁决过则跳过。
    62	  if (!in.has_decision) {
    63	    out.kind = PeriodicPublishKind::kSkip;
    64	    return out;
    65	  }
    66	  out.kind = PeriodicPublishKind::kDecision;
    67	  out.linear_x_mps = in.last_linear_x_mps;
    68	  out.linear_y_mps = in.last_linear_y_mps;
    69	  out.angular_z_radps = in.last_angular_z_radps;
    70	  return out;
    71	}
    72	
    73	// 锁存型安全源覆写：estop / 自动故障锁存 / bumper 属于"状态"而非"瞬时事件"。
    74	// 门控事件带 TTL（防止瞬态故障永久锁存），但锁存状态不随 TTL 解除——
    75	// 若只依赖 gate 事件，事件过期后 raw 路径会重新放行非零速度，与周期帧的
    76	// 零速形成交替发布，E-stop 期间底盘仍可能蠕动。因此 raw 裁决路径必须在
    77	// 门控之后再做一次锁存覆写，与 ComputePeriodicPublish 的首分支语义对齐。
