    79	                               amr_dispatcher_core::safety::CmdVelGateDecision& decision) {
    80	  if (!estop_or_fault && !bumper) return;
    81	  decision.allowed = false;
    82	  decision.linear_x_mps = 0.0;
    83	  decision.linear_y_mps = 0.0;
    84	  decision.angular_z_radps = 0.0;
    85	  decision.severity = amr_dispatcher_core::safety::SafetySeverity::kCritical;
    86	  decision.reason = estop_or_fault ? "estop" : "bumper";
    87	}
