    20	namespace amr_dispatcher_ros {
    21	
    22	// 选车结果对应的调度动作。
    23	enum class AssignmentDispatchAction {
    24	  kDispatch,             // 继续派发
    25	  kStayQueued,           // 暂时不可用 -> 留队等待
