     9	// I1：多源健康报告的新鲜度判定（纯函数，可脱离 rclcpp 单测）。
    10	// 时效打点必须发生在**真实数据到达点**（各订阅回调），而不是巡检调用周期——
    11	// 否则上游发布者死亡后，调用周期会无限"续命"，失联检测完全失效。
    12	// 只对周期性数据源做时效判定；estop 属一次性锁存信号（latched QoS 语义），
    13	// 不参与——对锁存源打点会把"不重复发送"误判为过期。
    14	struct ReportFreshness {
    15	  bool chassis = false;  // /chassis/link_health 本轮是否有新数据
    16	  bool watchdog = false; // 心跳（chassis_driver / path_tracker）本轮是否有新数据
    17	};
    18	
    19	// last_arrival：各数据源最后一次真实到达时刻；tolerance：容忍窗口
    20	//（应覆盖发布周期的数倍，避免抖动误判为陈旧）。
    21	// 从未到达的源保持 false —— 由 FaultSupervisor 的"从未上报不参与时效"语义兜底。
    22	inline ReportFreshness MakeReportFreshness(
    23	    const std::unordered_map<std::string, std::chrono::steady_clock::time_point>& last_arrival,
    24	    std::chrono::steady_clock::time_point now,
    25	    std::chrono::steady_clock::duration tolerance) {
    26	  ReportFreshness fresh;
    27	  const auto is_fresh = [&](const char* key) {
    28	    const auto it = last_arrival.find(key);
    29	    if (it == last_arrival.end()) return false;
    30	    return (now - it->second) <= tolerance;
    31	  };
    32	  fresh.chassis = is_fresh("chassis");
    33	  fresh.watchdog = is_fresh("watchdog");
    34	  return fresh;
    35	}
    36	
    37	}  // namespace amr_dispatcher_ros
