    10	
    11	#include <gtest/gtest.h>
    12	
    13	#include <string>
    14	
    15	using namespace amr_dispatcher_ros;
    16	using amr_dispatcher_core::fleet::AssignmentOutcome;
    17	using amr_dispatcher_core::fleet::VehicleAssignmentDecision;
    18	
    19	TEST(AssignmentDispatchDecisionTest, AssignedDispatches) {
    20	  VehicleAssignmentDecision decision;
    21	  decision.outcome = AssignmentOutcome::kAssigned;
    22	  decision.vehicle_id = "amr_01";
    23	  decision.strategy = "nearest";
    24	
    25	  const auto result = DecideAssignmentDispatch(decision);
    26	
    27	  EXPECT_EQ(result.action, AssignmentDispatchAction::kDispatch);
    28	  EXPECT_EQ(result.strategy, "nearest");
    29	  EXPECT_TRUE(result.reason.empty());
    30	}
    31	
    32	TEST(AssignmentDispatchDecisionTest, DeferredStaysQueuedAndKeepsReason) {
    33	  VehicleAssignmentDecision decision;
    34	  decision.outcome = AssignmentOutcome::kDeferred;
    35	  decision.reject_reason = "all vehicles busy";
    36	
    37	  const auto result = DecideAssignmentDispatch(decision);
    38	
    39	  EXPECT_EQ(result.action, AssignmentDispatchAction::kStayQueued);
    40	  EXPECT_EQ(result.reason, "all vehicles busy");
    41	}
    42	
    43	TEST(AssignmentDispatchDecisionTest, IndeterminatePausesAutoAssignment) {
    44	  VehicleAssignmentDecision decision;
    45	  decision.outcome = AssignmentOutcome::kIndeterminate;
    46	  decision.reject_reason = "no state report ever received";
    47	
    48	  const auto result = DecideAssignmentDispatch(decision);
    49	
    50	  EXPECT_EQ(result.action, AssignmentDispatchAction::kPauseAutoAssignment);
    51	  EXPECT_EQ(result.reason, "no state report ever received");
    52	}
    53	
    54	TEST(AssignmentDispatchDecisionTest, RejectedFailsPermanentlyWithReason) {
    55	  VehicleAssignmentDecision decision;
    56	  decision.outcome = AssignmentOutcome::kRejected;
    57	  decision.reject_reason = "requested vehicle not in managed list";
    58	
    59	  const auto result = DecideAssignmentDispatch(decision);
    60	
    61	  EXPECT_EQ(result.action, AssignmentDispatchAction::kReject);
    62	  EXPECT_EQ(result.reason, "requested vehicle not in managed list");
    63	}
    64	
    65	TEST(AssignmentDispatchDecisionTest, DeferredAndRejectedAreDistinctActions) {
    66	  // 这条断言锁住"失败 vs 排队"的语义分界：两者绝不能塌缩成同一动作
    67	  VehicleAssignmentDecision deferred;
    68	  deferred.outcome = AssignmentOutcome::kDeferred;
    69	  VehicleAssignmentDecision rejected;
    70	  rejected.outcome = AssignmentOutcome::kRejected;
