=== test_nav_pose_builder.cpp ===
     1	#include "amr_dispatcher_ros/nav_pose_builder.hpp"
     2	
     3	#include <gtest/gtest.h>
     4	
     5	#include <cmath>
     6	
     7	using namespace amr_dispatcher_ros;
     8	
     9	namespace {
    10	
    11	geometry_msgs::msg::PoseStamped MakeWp(double x, double y, double qz, double qw) {
    12	  geometry_msgs::msg::PoseStamped ps;
    13	  ps.pose.position.x = x;
    14	  ps.pose.position.y = y;
    15	  ps.pose.orientation.z = qz;
    16	  ps.pose.orientation.w = qw;
    17	  return ps;
    18	}
    19	
    20	}  // namespace
    21	
    22	// B3：单航点必须保留调用方给的原始四元数（不得被 atan2 覆盖为单位姿态）。
    23	// 例如 dispatcher 在 action 后端下用 wp.theta 编码站点朝向，覆盖成 yaw=0 会让
    24	// 车辆到站后回正——丢失终端姿态约束。
    25	TEST(NavPoseBuilder, SingleWaypointPreservesOrientation) {
    26	  const double target_yaw = 1.2;  // 任意非零朝向
    27	  const double qz = std::sin(target_yaw / 2.0);
    28	  const double qw = std::cos(target_yaw / 2.0);
    29	  const auto out = BuildNavPoses({MakeWp(3.0, 4.0, qz, qw)});
    30	  ASSERT_EQ(out.size(), 1u);
    31	  EXPECT_DOUBLE_EQ(out[0].pose.position.x, 3.0);
    32	  EXPECT_DOUBLE_EQ(out[0].pose.position.y, 4.0);
    33	  EXPECT_DOUBLE_EQ(out[0].pose.orientation.z, qz);
    34	  EXPECT_DOUBLE_EQ(out[0].pose.orientation.w, qw);
    35	  EXPECT_EQ(out[0].header.frame_id, "map");
    36	}
    37	
    38	// B3：多航点时仍按相邻点 atan2 重写航向（与原行为一致）
    39	TEST(NavPoseBuilder, MultiWaypointOverwritesOrientation) {
    40	  const auto out = BuildNavPoses({MakeWp(0.0, 0.0, 0.9, 0.1),  // 起点原始姿态应被覆盖
    41	                                  MakeWp(1.0, 0.0, 0.0, 1.0)});
    42	  ASSERT_EQ(out.size(), 2u);
    43	  // 航向 = atan2(0-0, 1-0) = 0 -> z=0 w=1
    44	  EXPECT_DOUBLE_EQ(out[0].pose.orientation.z, 0.0);
    45	  EXPECT_DOUBLE_EQ(out[0].pose.orientation.w, 1.0);
    46	  // 末点沿用最后一段朝向 -> 也是 yaw=0
    47	  EXPECT_DOUBLE_EQ(out[1].pose.orientation.z, 0.0);
    48	  EXPECT_DOUBLE_EQ(out[1].pose.orientation.w, 1.0);
    49	}
    50	
    51	// B3：空输入返回空
    52	TEST(NavPoseBuilder, EmptyInputReturnsEmpty) {
    53	  EXPECT_TRUE(BuildNavPoses({}).empty());
    54	}
