     1	#include "amr_dispatcher_ros/report_freshness.hpp"
     2	
     3	#include <gtest/gtest.h>
     4	
     5	#include <chrono>
     6	
     7	using namespace amr_dispatcher_ros;
     8	using namespace std::chrono_literals;
     9	
    10	namespace {
    11	using Clock = std::chrono::steady_clock;
    12	using ArrivalMap = std::unordered_map<std::string, Clock::time_point>;
    13	}  // namespace
    14	
    15	// 数据在容忍窗口内到达 -> 新鲜
    16	TEST(ReportFreshness, RecentArrivalIsFresh) {
    17	  const auto now = Clock::now();
    18	  ArrivalMap m{{"chassis", now - 100ms}, {"watchdog", now - 200ms}};
    19	  const auto fresh = MakeReportFreshness(m, now, 1000ms);
    20	  EXPECT_TRUE(fresh.chassis);
    21	  EXPECT_TRUE(fresh.watchdog);
    22	}
    23	
    24	// 超出容忍窗口 -> 陈旧（上游发布者死亡的检测信号）
    25	TEST(ReportFreshness, StaleArrivalIsNotFresh) {
    26	  const auto now = Clock::now();
    27	  ArrivalMap m{{"chassis", now - 3000ms}, {"watchdog", now - 100ms}};
    28	  const auto fresh = MakeReportFreshness(m, now, 1000ms);
    29	  EXPECT_FALSE(fresh.chassis);
    30	  EXPECT_TRUE(fresh.watchdog);
    31	}
    32	
    33	// 从未到达过的源不判新鲜——由"从未上报不参与时效"语义兜底
    34	TEST(ReportFreshness, NeverArrivedIsNotFresh) {
    35	  const auto now = Clock::now();
    36	  ArrivalMap m{{"watchdog", now - 100ms}};
    37	  const auto fresh = MakeReportFreshness(m, now, 1000ms);
    38	  EXPECT_FALSE(fresh.chassis);
    39	  EXPECT_TRUE(fresh.watchdog);
    40	}
    41	
    42	// 恰好等于容忍窗口不算过期（严格超出才陈旧）
    43	TEST(ReportFreshness, BoundaryWindowIsStillFresh) {
    44	  const auto now = Clock::now();
    45	  ArrivalMap m{{"chassis", now - 1000ms}};
    46	  const auto fresh = MakeReportFreshness(m, now, 1000ms);
    47	  EXPECT_TRUE(fresh.chassis);
    48	}
