     1	#include "amr_dispatcher_ros/safety_publish_decision.hpp"
     2	
     3	#include <gtest/gtest.h>
     4	
     5	#include <chrono>
     6	
     7	using namespace amr_dispatcher_ros;
     8	using namespace std::chrono_literals;
     9	
    10	namespace {
    11	
    12	PeriodicPublishInput MakeInput() {
    13	  PeriodicPublishInput in;
    14	  in.now = std::chrono::steady_clock::now();
    15	  in.last_raw_stamp = in.now;
    16	  in.has_last_raw_stamp = true;
    17	  in.has_decision = true;
    18	  in.last_linear_x_mps = 0.5;
    19	  in.last_angular_z_radps = 0.2;
    20	  in.heartbeat_timeout = 500ms;
    21	  return in;
    22	}
    23	
    24	}  // namespace
    25	
    26	// B1：estop/auto_fault/bumper/critical 任一激活 -> 周期帧强制零速
    27	TEST(SafetyPublishDecision, EStopForcesZero) {
    28	  auto in = MakeInput();
    29	  in.estop_or_fault = true;
    30	  const auto out = ComputePeriodicPublish(in);
    31	  EXPECT_EQ(out.kind, PeriodicPublishKind::kZero);
    32	  EXPECT_DOUBLE_EQ(out.linear_x_mps, 0.0);
    33	  EXPECT_DOUBLE_EQ(out.angular_z_radps, 0.0);
    34	  EXPECT_EQ(out.reason, "estop");
    35	}
    36	
    37	TEST(SafetyPublishDecision, BumperForcesZero) {
    38	  auto in = MakeInput();
    39	  in.bumper = true;
    40	  const auto out = ComputePeriodicPublish(in);
    41	  EXPECT_EQ(out.kind, PeriodicPublishKind::kZero);
    42	  EXPECT_EQ(out.reason, "bumper");
    43	}
    44	
    45	TEST(SafetyPublishDecision, CriticalDecisionForcesZero) {
    46	  auto in = MakeInput();
    47	  in.decision_critical = true;
    48	  const auto out = ComputePeriodicPublish(in);
    49	  EXPECT_EQ(out.kind, PeriodicPublishKind::kZero);
    50	  EXPECT_EQ(out.reason, "critical_event");
    51	}
    52	
    53	// B1：/cmd_vel_raw 超过 heartbeat_timeout 未收到 -> 周期零速兜底
    54	TEST(SafetyPublishDecision, StaleRawForcesZero) {
    55	  auto in = MakeInput();
    56	  in.last_raw_stamp = in.now - 600ms;
    57	  const auto out = ComputePeriodicPublish(in);
    58	  EXPECT_EQ(out.kind, PeriodicPublishKind::kZero);
    59	  EXPECT_EQ(out.reason, "cmd_vel_raw_stale");
    60	}
    61	
    62	// 边界：恰好等于阈值不算过期（严格大于才触发）
    63	TEST(SafetyPublishDecision, BoundaryTimeoutNotStale) {
    64	  auto in = MakeInput();
    65	  in.last_raw_stamp = in.now - 500ms;
    66	  const auto out = ComputePeriodicPublish(in);
    67	  EXPECT_EQ(out.kind, PeriodicPublishKind::kDecision);
    68	  EXPECT_DOUBLE_EQ(out.linear_x_mps, 0.5);
    69	  EXPECT_DOUBLE_EQ(out.angular_z_radps, 0.2);
    70	}
    71	
    72	// 正常路径：重放最近一次裁决结果
    73	TEST(SafetyPublishDecision, ReplaysLastDecision) {
    74	  auto in = MakeInput();
    75	  in.last_raw_stamp = in.now - 100ms;  // 新鲜
    76	  const auto out = ComputePeriodicPublish(in);
    77	  EXPECT_EQ(out.kind, PeriodicPublishKind::kDecision);
    78	  EXPECT_DOUBLE_EQ(out.linear_x_mps, 0.5);
    79	  EXPECT_DOUBLE_EQ(out.linear_y_mps, 0.0);
    80	  EXPECT_DOUBLE_EQ(out.angular_z_radps, 0.2);
    81	}
    82	
    83	// 从未收到过 raw：不发任何帧（系统还没开始运动，持续零速无意义）
    84	TEST(SafetyPublishDecision, NeverReceivedSkips) {
    85	  auto in = MakeInput();
    86	  in.has_decision = false;
    87	  in.has_last_raw_stamp = false;
    88	  const auto out = ComputePeriodicPublish(in);
    89	  EXPECT_EQ(out.kind, PeriodicPublishKind::kSkip);
    90	}
    91	
    92	// 锁存型安全源覆写（estop/bumper/自动故障）：事件 TTL 过期不等于故障解除，
    93	// 只要锁存状态仍激活，raw 裁决路径必须被强制零速 critical。
    94	namespace {
    95	amr_dispatcher_core::safety::CmdVelGateDecision MakeAllowedDecision() {
    96	  amr_dispatcher_core::safety::CmdVelGateDecision d;
    97	  d.allowed = true;
    98	  d.linear_x_mps = 0.8;
    99	  d.linear_y_mps = 0.1;
   100	  d.angular_z_radps = 0.3;
   101	  d.severity = amr_dispatcher_core::safety::SafetySeverity::kInfo;
   102	  d.reason = "pass";
   103	  return d;
   104	}
   105	}  // namespace
   106	
   107	TEST(LatchedBlocks, EstopLatchedOverridesToZero) {
   108	  auto d = MakeAllowedDecision();
   109	  ApplyLatchedBlocks(/*estop_or_fault=*/true, /*bumper=*/false, d);
   110	  EXPECT_FALSE(d.allowed);
   111	  EXPECT_DOUBLE_EQ(d.linear_x_mps, 0.0);
   112	  EXPECT_DOUBLE_EQ(d.linear_y_mps, 0.0);
   113	  EXPECT_DOUBLE_EQ(d.angular_z_radps, 0.0);
   114	  EXPECT_EQ(d.severity, amr_dispatcher_core::safety::SafetySeverity::kCritical);
   115	  EXPECT_EQ(d.reason, "estop");
   116	}
   117	
   118	TEST(LatchedBlocks, BumperLatchedOverridesToZero) {
   119	  auto d = MakeAllowedDecision();
   120	  ApplyLatchedBlocks(false, true, d);
   121	  EXPECT_FALSE(d.allowed);
   122	  EXPECT_DOUBLE_EQ(d.linear_x_mps, 0.0);
   123	  EXPECT_EQ(d.severity, amr_dispatcher_core::safety::SafetySeverity::kCritical);
   124	  EXPECT_EQ(d.reason, "bumper");
   125	}
   126	
   127	TEST(LatchedBlocks, NoLatchKeepsDecisionUnchanged) {
   128	  auto d = MakeAllowedDecision();
   129	  ApplyLatchedBlocks(false, false, d);
   130	  EXPECT_TRUE(d.allowed);
   131	  EXPECT_DOUBLE_EQ(d.linear_x_mps, 0.8);
   132	  EXPECT_DOUBLE_EQ(d.angular_z_radps, 0.3);
   133	  EXPECT_EQ(d.reason, "pass");
   134	}

