    23	// 例如 dispatcher 在 action 后端下用 wp.theta 编码站点朝向，覆盖成 yaw=0 会让
    24	// 车辆到站后回正——丢失终端姿态约束。
    25	TEST(NavPoseBuilder, SingleWaypointPreservesOrientation) {
    26	  const double target_yaw = 1.2;  // 任意非零朝向
    27	  const double qz = std::sin(target_yaw / 2.0);
    28	  const double qw = std::cos(target_yaw / 2.0);
    29	  const auto out = BuildNavPoses({MakeWp(3.0, 4.0, qz, qw)});
    30	  ASSERT_EQ(out.size(), 1u);
    31	  EXPECT_DOUBLE_EQ(out[0].pose.position.x, 3.0);
    32	  EXPECT_DOUBLE_EQ(out[0].pose.position.y, 4.0);
    33	  EXPECT_DOUBLE_EQ(out[0].pose.orientation.z, qz);
    34	  EXPECT_DOUBLE_EQ(out[0].pose.orientation.w, qw);
    35	  EXPECT_EQ(out[0].header.frame_id, "map");
