 57	/**
 58	 * @brief 真实折线路径规划器 (Skeleton Planner)
 59	 * 基于 StationCatalog 混合图（stations + road_nodes）：先由 FindRoutePath
 60	 * 在混合图上执行 Dijkstra 选出节点序列，再顺序拼接各边的真实几何折线
 61	 * （支持双向边反向展开与缺失折线的直线退化），最后按 step_size 等距插值
 62	 * 输出带航向角的 Pose2D 路点序列，供底盘循迹到站。
 63	 */
 64	class SkeletonPlanner : public IPathPlanner {
 65	 public:
 66	  struct Config {
 67	    double step_size = 0.1;  // 采样重插值步长 (米)
 68	  };
 69	
 70	  // GCC 不允许在类定义内的默认参数中对含 NSDMI 的嵌套 Config 做
 71	  // `= {}` 聚合值初始化（"default member initializer ... required before the
 72	  // end of its enclosing class"），故按仓库惯例（PurePursuitController）
 73	  // 用委托构造暴露单参形式。
 74	  explicit SkeletonPlanner(catalog::StationCatalog catalog, Config config);
 75	  SkeletonPlanner(catalog::StationCatalog catalog)
 76	      : SkeletonPlanner(std::move(catalog), Config{}) {}
 77	
 78	  void UpdateCatalog(catalog::StationCatalog catalog);
 79	  const catalog::StationCatalog& catalog() const { return catalog_; }
 80	
 81	  // 实现 IPathPlanner：吸附最近路网节点规划；start/goal 与节点间的间隙
 82	  // 自动拼接接驳直线段，首尾路点严格等于 start/goal。
 83	  std::vector<Pose2D> Plan(const Pose2D& start, const Pose2D& goal,
 84	                           const std::string& edge_id = "") override;
 85	  std::string GetPlannerName() const override { return "SkeletonPlanner"; }
 86	
 87	  // 支持直接按站点 / 路网节点 ID 规划（不做接驳，路点全部落在图折线上）
 88	  std::vector<Pose2D> PlanBetweenNodes(const std::string& from_node,
 89	                                       const std::string& to_node);
 90	
 91	 private:
 92	  catalog::StationCatalog catalog_;
 93	  Config config_;
 94	};
