109	// 业务站点锚点（来自 markers.yaml）：世界坐标 + 语义类型。
110	struct AnchorStation {
111	  std::string id;
112	  std::string type = "normal";  // "pickup", "dropoff", "charge", etc.
113	  double x = 0.0;
114	  double y = 0.0;
115	  double yaw = 0.0;
116	};
117	
118	struct TopologyBuilderConfig {
119	  // 站点距离最近路网边的最大吸附允许距离（米），超过则构建失败。
120	  double max_snap_dist_m = 2.0;
121	  std::string map_hash;
122	  std::string graph_version = "v1";
123	};
124	
125	struct TopologyBuildResult {
126	  bool success = false;
127	  std::string error_message;
128	  catalog::StationCatalog catalog;
129	};
130	
131	// 拓扑路网构建与站点吸附边拆分。
132	//
133	// 算法流水线：
134	//   1. 骨架特征点提取：识别 8 邻域环连通组数 != 2 的骨架像素
135	//      （端点=1、分叉点>=3、孤立点=0），每个特征点生成 RoadNode。
136	//      纯闭合环（无特征点）任取一环上像素作为 RoadNode，避免环丢失。
137	//   2. 骨架链追踪：从特征点沿骨架追踪到下一特征点，生成 CatalogStationEdge，
138	//      polyline 保存真实折线像素序列（世界坐标），distance_m 为累加长度。
139	//   3. 站点吸附：将每个 AnchorStation 正交投影到最近边的 polyline，
140	//      距离超过 max_snap_dist_m 时报错；投影点处将原边拆分为两条子边，
141	//      站点作为新节点接入路网。
142	//   4. 连通性校验：所有站点必须处于同一连通分量（通过 FindRoutePath 验证）。
143	//   5. 版本标记：写入 map_hash / graph_version，最后经 ValidateStationCatalog 校验。
144	TopologyBuildResult BuildTopologyCatalog(
145	    const BinaryGrid& skeleton, const MapGrid& map_info,
146	    const std::vector<AnchorStation>& anchors,
147	    const TopologyBuilderConfig& config);
