157	#include <vector>
158	
159	#include "amr_dispatcher_core/planning/path_planner_interface.hpp"
160	
161	namespace amr_dispatcher_core {
162	
163	/**
164	 * @brief 轻量基准线性路径规划器 (Mock / Baseline 实现)
165	 * 在起点与终点之间做等距几何插值，不依赖外部代价地图与复杂搜索算法。
166	 * 用于系统基础设施链路验证、极速单测与全流程调度跑通。
167	 */
168	class MockLinearPlanner : public IPathPlanner {
169	 public:
170	  explicit MockLinearPlanner(double step_size = 0.1) : step_size_(step_size) {
171	    if (step_size_ <= 0.0) {
172	      step_size_ = 0.1;
173	    }
174	  }
175	
176	  std::vector<Pose2D> Plan(const Pose2D& start, const Pose2D& goal,
177	                           const std::string& /*edge_id*/ = "") override {
178	    std::vector<Pose2D> path;
179	    const double dx = goal.x - start.x;
180	    const double dy = goal.y - start.y;
181	    const double distance = std::hypot(dx, dy);
182	
183	    if (distance < 1e-4) {
184	      path.push_back(start);
185	      return path;
186	    }
187	
188	    const double heading = std::atan2(dy, dx);
189	    const int num_steps = static_cast<int>(std::ceil(distance / step_size_));
190	
191	    path.reserve(num_steps + 1);
192	    for (int i = 0; i <= num_steps; ++i) {
193	      const double ratio = static_cast<double>(i) / num_steps;
194	      Pose2D p;
195	      p.x = start.x + ratio * dx;
196	      p.y = start.y + ratio * dy;
197	      p.theta = (i == num_steps) ? goal.theta : heading;
198	      path.push_back(p);
199	    }
200	
201	    return path;
202	  }
203	
204	  std::string GetPlannerName() const override { return "MockLinearPlanner"; }
205	
206	  double GetStepSize() const { return step_size_; }
207	  void SetStepSize(double step_size) {
208	    if (step_size > 0.0) {
209	      step_size_ = step_size;
210	    }
211	  }
212	
213	 private:
214	  double step_size_{0.1};
215	};
216	
217	}  // namespace amr_dispatcher_core

