 29	// 死锁检测输入快照：调用方从外部聚合 mission 状态 + traffic_reservation 状态。
 30	struct DeadlockSnapshot {
 31	  std::vector<Mission> active_missions;          // 当前 ACTIVE 的任务
 32	  std::unordered_map<std::string, std::chrono::steady_clock::time_point> last_progress;
 33	  std::unordered_map<std::string, std::chrono::steady_clock::time_point> reservation_acquired_at;
 34	  std::unordered_set<std::string> reserved_resource_ids;
 35	
