 40	// 检测结论：单次 Detect 返回的所有嫌疑。
 41	enum class DeadlockKind {
 42	  kIdleActive,            // ACTIVE 任务在 idle_threshold 内无 progress
 43	  kLongReservationHold,   // 持有资源超过阈值
 44	  kMutualBlock,           // 依赖环死锁 (Wait-For Graph 存在环)
 45	  kOverCapacity,          // 活跃任务数超限：派发过载而非互斥死锁，recovery 不得 pause
 46	};
