 48	struct DeadlockFinding {
 49	  std::vector<std::string> mission_ids;  // 涉及的 mission_id
 50	  DeadlockKind kind = DeadlockKind::kIdleActive;
 51	  std::string description;
 52	  std::vector<std::string> cycle_path;   // 具体的成环路径：任务与资源交替并闭合回起始
 53	                                          // 任务，例如 [m1, route_edge:A__B, m2,
 54	                                          // route_node:C, m1]（偶数位任务、奇数位资源）
