 98	// 优先级任务队列。
 99	// - 排序委托可插拔 MissionComparator（默认 priority FIFO）；
100	// - 入队拒绝重复 id 与超容量；
101	// - 支持按 order_id 整单暂停/恢复（暂停任务出队时跳过而非删除）；
102	// - 非线程安全，由上层（节点层）保证单线程访问或加锁。
103	class MissionQueue {
104	 public:
105	  struct Config {
106	    std::size_t max_size = 128;
107	    std::string comparator = "priority_fifo";
108	  };
109	
110	  struct PushResult {
111	    bool accepted = false;
112	    std::string message;
113	  };
114	
115	  struct PopResult {
116	    bool success = false;
117	    bool queue_empty = false;
118	    bool all_paused = false;   // 队列非空但全部处于暂停订单
119	    std::string message;
120	    std::optional<Mission> mission;
121	  };
122	
123	  explicit MissionQueue(Config config);
124	  MissionQueue() : MissionQueue(Config{}) {}
125	
126	  // 替换排序策略（转移所有权）。替换后立即重排。
127	  void SetComparator(std::unique_ptr<MissionComparator> comparator);
128	  std::string comparator_name() const { return comparator_->name(); }
129	
130	  PushResult Push(Mission mission);
131	  PopResult PopNext();
132	  const Mission* Peek() const;
133	
134	  // 按出队顺序导出前 N 个**未暂停**的排队任务（head-of-line 规避用）。
135	  // 队首任务可能因"暂无合格车辆"而暂时派不出去，此时必须能继续看后面的任务，
136	  // 否则一个不可派的队首会把整条队列堵死。
137	  std::vector<Mission> PeekN(std::size_t max_count) const;
138	
139	  // 按 mission_id 精确出队（配合 PeekN：跳过不可派的队首，直接出后续可派任务）。
140	  // 找不到或该单处于暂停状态时返回失败，不改变队列内容。
141	  PopResult PopById(const std::string& mission_id);
142	
143	  // 返回 true 表示命中并删除；同时清理该订单的暂停标记。
144	  bool Cancel(const std::string& mission_id);
145	
146	  // 调整排队中任务的优先级并恢复堆序；不存在返回 false。
147	  bool Reprioritize(const std::string& mission_id, int priority);
148	
149	  // 整单暂停/恢复（作用于 order_id，不影响任务状态字段本身）。
150	  void PauseOrder(const std::string& order_id);
151	  void ResumeOrder(const std::string& order_id);
152	  bool IsOrderPaused(const std::string& order_id) const;
153	  std::size_t CancelOrder(const std::string& order_id);  // 整单取消，返回删除数
154	
155	  std::size_t size() const { return items_.size(); }
156	  bool empty() const { return items_.empty(); }
157	  std::size_t capacity() const { return config_.max_size; }
158	  bool Contains(const std::string& mission_id) const;
159	
160	  // 按出队顺序导出快照（调度状态话题/CLI 列表用）。
161	  std::vector<Mission> Snapshot() const;
162	
163	 private:
164	  void Sort() const;
165	
166	  Config config_;
167	  std::unique_ptr<MissionComparator> comparator_;
168	  std::vector<Mission> items_;
169	  std::unordered_set<std::string> paused_order_ids_;
170	  mutable bool dirty_ = false;  // 惰性排序：入队/改优先级只置脏，出队前重排
171	};
