185	// 时空预约区间：[start_time, end_time]
186	struct TimeInterval {
187	  std::chrono::steady_clock::time_point start;
188	  std::chrono::steady_clock::time_point end;
189	
190	  bool OverlapsWith(const TimeInterval& other) const {
191	    return start < other.end && other.start < end;
192	  }
193	};
