201	// 资源预留表：兼具静态原子锁与时空预约区间锁（Time-Space Reservation）
202	class ResourceTable {
203	 public:
204	  struct ReserveResult {
205	    bool success = false;
206	    std::string message;
207	    std::vector<std::string> newly_reserved;  // 失败时已全部回滚，保持原子性
208	  };
209	
210	  struct ReleaseResult {
211	    bool released = false;
212	    std::string message;
213	  };
214	
215	  // 原子静态排他预留：任一资源被他人持有则整体失败且不落锁。
216	  ReserveResult Reserve(const std::string& mission_id,
217	                        const std::vector<std::string>& resource_ids);
218	
219	  // 时空窗口预约：允许多车错峰占用同一路段，只要时间窗口不重叠即可并行预约！
220	  bool ReserveTimeSpace(const std::string& mission_id,
221	                        const std::string& resource_id,
222	                        std::chrono::steady_clock::time_point start,
223	                        std::chrono::steady_clock::time_point end,
224	                        std::string* message);
225	
226	  // 释放某任务持有的全部资源（含时空预约），返回是否实际删除。
227	  ReleaseResult Release(const std::string& mission_id);
228	
229	  // 逐段动态解锁：仅释放 owner == mission_id 且列于 resource_ids 的锁。
230	  // 他人锁（含 traffic_block）、未持有/已释放的 id 一律跳过（对未持有 id 是安全 no-op）。
231	  // 返回实际删除的 resource_id 列表（保序、与入参一致），供幂等重算与日志取证。
232	  // 注意：只处理静态锁；时空预约不在逐段释放语义内（Release(mission) 才全清）。
233	  std::vector<std::string> ReleaseResources(
234	      const std::string& mission_id, const std::vector<std::string>& resource_ids);
235	
236	  // 时空预约**批量**提交（全有或全无）：一条路径涉及多个资源，
237	  // 必须整条路径全部预约成功才落表；任一失败则全部回滚，不留半套预约。
238	  // 逐个调用 ReserveTimeSpace 无法保证这一点（中途失败会留下前面的预约）。
239	  // 返回失败时 message 给出冲突资源与占用方。
240	  bool ReserveTimeSpaceBatch(
241	      const std::string& mission_id,
242	      const std::vector<std::pair<std::string, TimeInterval>>& resource_intervals,
243	      std::string* message);
244	
245	  // 延长某任务在某资源上的时空窗口（车辆执行滞后时用）。
246	  // 延长区间与他人预约冲突则不改动（返回 false）。
247	  bool ExtendTimeSpaceReservation(const std::string& mission_id, const std::string& resource_id,
248	                                  const std::chrono::steady_clock::time_point& new_end,
249	                                  std::string* message);
250	
251	  // 逐资源释放某任务持有的时空预约区间（车辆**确认驶离**后调用）。
252	  //   * 只释放 owner == mission_id 的区间，他人区间不动；
253	  //   * 该任务在某资源上没有区间 -> 幂等跳过；
254	  // 返回实际释放的资源 id 列表（保序）。
