305	// 可插拔队列排序策略（策略模式）。
306	// 内置实现见 mission_comparator.cpp；新增调度策略只需：
307	//   1) 继承 MissionComparator；
308	//   2) 在 CreateMissionComparator 工厂注册表加一行。
309	class MissionComparator {
310	 public:
311	  virtual ~MissionComparator() = default;
312	
313	  virtual std::string name() const = 0;
314	
315	  // 严格弱序：a 比 b 更应先出队时返回 true。
316	  // 实现必须保证自反/反对称/传递，否则 std::sort 行为未定义。
317	  // sequence 字段是各策略最终打破平局的兜底键。
318	  virtual bool Before(const Mission& a, const Mission& b) const = 0;
319	};
320	
321	// priority 降序 → sequence 升序。默认策略，先到先服务同优先级。
322	class PriorityFifoComparator final : public MissionComparator {
323	 public:
324	  std::string name() const override { return "priority_fifo"; }
325	  bool Before(const Mission& a, const Mission& b) const override;
326	};
327	
328	// 最早截止期优先（EDF）。deadline_unix_ms <= 0 视为无限远，排最后。
329	class DeadlineComparator final : public MissionComparator {
330	 public:
331	  std::string name() const override { return "earliest_deadline"; }
332	  bool Before(const Mission& a, const Mission& b) const override;
333	};
334	
335	// 最短预估耗时优先（SJF），适合提升平均周转。
336	class ShortestJobComparator final : public MissionComparator {
337	 public:
338	  std::string name() const override { return "shortest_job"; }
339	  bool Before(const Mission& a, const Mission& b) const override;
340	};
341	
342	// 加权得分 = w_p·priority + w_d·deadline_score + w_s·speed_score。
343	// 三个权重从配置注入，得分相同退回 FIFO。演示可扩展性卖点。
344	class WeightedScoreComparator final : public MissionComparator {
345	 public:
346	  struct Weights {
347	    double priority = 1.0;
348	    double deadline = 0.5;    // 距截止期越近得分越高
349	    double expected_time = 0.2;  // 预估耗时越短得分越高
350	    std::int64_t horizon_ms = 10 * 60 * 1000;  // 截止期得分归一化窗口
351	  };
352	
353	  explicit WeightedScoreComparator(Weights weights);
354	  WeightedScoreComparator() : WeightedScoreComparator(Weights{}) {}
355	
356	  std::string name() const override { return "weighted_score"; }
357	  bool Before(const Mission& a, const Mission& b) const override;
358	
359	  // 暴露给测试：同序保证 score(a)==score(b) ⇔ !Before(a,b) && !Before(b,a)。
360	  double Score(const Mission& m, std::int64_t now_unix_ms) const;
361	
362	 private:
363	  Weights weights_;
364	};
365	
366	// 工厂：未知名称返回 nullptr。name 表：
367	//   "priority_fifo" | "earliest_deadline" | "shortest_job" | "weighted_score"
368	std::unique_ptr<MissionComparator> CreateMissionComparator(const std::string& name);
369	
370	std::vector<std::string> RegisteredComparatorNames();
