191	// 强清决策结果。
192	struct ForceClearLinkDecision {
193	  // 是否受理本次强清。
194	  bool allowed = false;
195	  // 拒绝原因（allowed == false 时有效）。
196	  std::string reject_reason;
197	  // 归属该车名下、需释放的锁（按 mission 分组：mission_id -> resource_id 列表）。
198	  // ReleaseResources(mission_id, ids) 按组释放，owner 校验在核心内完成。
199	  std::unordered_map<std::string, std::vector<std::string>> locks_by_mission;
200	  // 需收口（作废）的在途 mission id——车辆已死，这些任务永远不会到达，
201	  // 必须显式收口释放执行槽位，否则后续任务永远排不上。
202	  std::vector<std::string> missions_to_abort;
