 75	  std::string required_capability = "transport";
 76	  // 最低电量阈值（百分比）。默认 0（不过滤）。
 77	  double min_battery_percent = 0.0;
 78	  // 状态最大时延（毫秒）：超过则视为"状态不确定"。默认 5000。
 79	  int64_t state_max_age_ms = 5000;
 80	  // vehicle_id -> 到 pickup 的路径成本（米）。缺项 = 距离不可算。
 81	  std::unordered_map<std::string, double> distance_to_pickup_m;
 82	};
