 84	// 选车结果分类。
 85	enum class AssignmentOutcome {
 86	  kAssigned,        // 已选车
 87	  kDeferred,        // 暂时不可用 -> 任务留队等待
 88	  kIndeterminate,   // 状态不确定 -> 暂停自动分配，等待状态恢复
 89	  kRejected,        // 永久不满足 -> 拒绝
 90	};
