174	  // 操作员标识（必填，写入审计）。
175	  std::string operator_id;
176	  // 操作原因（必填，写入审计）。
177	  std::string reason;
178	  // 目标车辆是否在受管清单内。
179	  bool vehicle_in_managed_list = false;
180	  // 目标车辆当前链路是否在线（true = 活车，拒绝强清）。
181	  bool vehicle_online = true;
182	  // 目标车辆是否已处于隔离态（已隔离则拒绝重复强清）。
183	  bool vehicle_quarantined = false;
184	  // mission_id -> 承接该单的车辆 id（下发订单时登记的绑定）。
185	  // 缺项表示该 mission 未由受管车辆承接（锁不归本车）。
186	  std::unordered_map<std::string, std::string> mission_vehicle_bindings;
187	  // resource_id -> 锁 owner（= mission_id）。由 ResourceTable::Snapshot() 采集。
188	  std::unordered_map<std::string, std::string> held_locks;
189	};
