198	  // ReleaseResources(mission_id, ids) 按组释放，owner 校验在核心内完成。
199	  std::unordered_map<std::string, std::vector<std::string>> locks_by_mission;
200	  // 需收口（作废）的在途 mission id——车辆已死，这些任务永远不会到达，
201	  // 必须显式收口释放执行槽位，否则后续任务永远排不上。
202	  std::vector<std::string> missions_to_abort;
203	};
204	
205	// 纯函数：给定强清上下文，产出强清决策。
206	// 判定顺序（任一不满足即拒绝，且不产生任何副作用）：
207	//   1. vehicle_id 非空；
208	//   2. confirm_vehicle_id 与 vehicle_id 完全一致（防打错车）；
209	//   3. operator_id 与 reason 非空（审计必填）；
210	//   4. 车辆在受管清单内；
211	//   5. 车辆当前离线（在线 = 误杀活车，拒绝）；
212	//   6. 车辆未处于隔离态（已隔离则拒绝重复强清）。
213	// 受理后：
214	//   - 收集绑定到该车的 mission（missions_to_abort）；
215	//   - 对每个绑定 mission，收集 held_locks 中 owner == 该 mission 的锁（locks_by_mission）。
216	//     绑定缺失的 owner（如 traffic_block: 前缀的封路、其它车辆的任务）一律不动。
217	ForceClearLinkDecision PlanForceClearLink(const ForceClearLinkRequest& request);
218	
219	// 恢复（解除隔离）决策的输入快照。
220	struct RestoreLinkRequest {
221	  std::string vehicle_id;
222	  std::string confirm_vehicle_id;
223	  std::string operator_id;
224	  std::string reason;
225	  bool vehicle_in_managed_list = false;
226	  bool vehicle_quarantined = false;   // 必须处于隔离态才可恢复
227	  bool vehicle_online = true;         // 在线才可恢复（离线车恢复后仍不可用）
228	  // 操作员是否已核实车辆物理位置（必填 true）：位置未核实的车不得回到调度池。
229	  bool position_verified = false;
230	};
231	
232	// 恢复决策结果。
233	struct RestoreLinkDecision {
234	  bool allowed = false;
235	  std::string reject_reason;
236	};
237	
238	RestoreLinkDecision PlanRestoreLink(const RestoreLinkRequest& request);
