233	// Rule 1（Spec §5.3 逐段释放）纯核心计算结果。
234	struct TrailingUnlockDecision {
235	  // lastNodeId 命中订单路径且 lastNodeSequenceId 与订单一致（节点 i 的 sequence = i*2）。
236	  // false 时一律不释放（保守处置：宁可少放，不可错放）。
237	  bool confirmed = false;
238	  // 严格位于确认位置身后、且当前确由 owner_mission_id 持有的路由锁 id 列表。
239	  std::vector<std::string> lock_ids_to_release;
240	  // 未确认时的处置指引（调度侧据此打 WARN 日志；确认时可为空）。
241	  std::string message;
242	};
243	
244	// Rule 1：根据小车确认的 lastNodeId/lastNodeSequenceId 计算应释放的身后路由锁。
245	//
246	// 参数:
247	//   order_path_node_ids: 本单行驶路径（travel order，如 station_A, rn_1, station_B）
248	//   confirmed_last_node_id: 小车 state 上报的 lastNodeId
249	//   confirmed_last_node_sequence_id: 小车 state 上报的 lastNodeSequenceId
250	//       （VDA 5050 订单节点 sequence = 下标 * 2，边占用两节点间的奇数槽位）
251	//   owner_mission_id: 锁的归属任务 id（= 订单 order_id = ResourceTable 预留 owner）
252	//   held_locks: resource_id -> owner 映射（通常由 ResourceTable::Snapshot() 构造）
253	//
254	// 足迹规则（保守）：确认位置 = path[k] 时
255	//   释放：path[0..k-1] 的节点锁 + path[0..k-2] 的边锁（整段越过的部分）
256	//   保留：path[k] 节点锁（当前所在节点）、(k-1,k) 边锁（刚驶离，车尾可能悬跨）、
257	//         (k,k+1) 边锁（正在行驶）以及前方全部锁（物理足迹不放）
258	//   lastNodeId 未命中路径 / sequence 与订单不符 / 空 lastNodeId
259	//     -> 不确认，释放集为空，message 附处置指引
260	// 所有权: 仅返回 held_locks 中 owner == owner_mission_id 的锁；
261	//   他人锁、快照中不存在（未持有）的 id 一律不返回（撞单/幂等安全）。
262	TrailingUnlockDecision PlanTrailingUnlock(
263	    const std::vector<std::string>& order_path_node_ids,
264	    const std::string& confirmed_last_node_id,
265	    uint32_t confirmed_last_node_sequence_id,
266	    const std::string& owner_mission_id,
267	    const std::unordered_map<std::string, std::string>& held_locks);
268	
269	// Rule 2（Spec §5.2 断链锁定保护）链路守卫决策（纯函数）。
270	struct DisconnectGuardDecision {
271	  // 铁律：任何链路状态下守卫都不产生释放动作——锁仅可由 Rule 1 的显式位置推进释放。
272	  bool retain_all_locks = true;
273	  bool block_new_dispatch = false;    // 离线：挂起向该车的新派发，直至 online=true
274	  bool emit_watchdog_warning = false; // 离线或状态陈旧：软看门狗告警
275	  std::string message;                // 告警文案（含 Spec 指引引用）
276	};
277	
278	// Rule 2：小车链路状态 -> 守卫决策。
279	//   离线（LWT CONNECTIONBROKEN / 心跳超时）：保留全部锁 + 挂起派发 + 告警；
280	//   在线但 state 陈旧：保留全部锁 + 告警（陈旧本身不是释放依据，也不阻塞派发）；
281	//   在线且新鲜：保留锁（释放只来自 Rule 1），放行派发，不告警。
282	DisconnectGuardDecision EvaluateVehicleLinkGuard(bool vehicle_online, bool state_stale);
