709	void DispatcherNode::ForceClearVda5050LinkCb(
710	    const std::shared_ptr<amr_dispatcher_interfaces::srv::ForceClearVda5050Link::Request> req,
711	    std::shared_ptr<amr_dispatcher_interfaces::srv::ForceClearVda5050Link::Response> resp) {
712	  // Task 7（终审 I1 闭合）：核心纯函数决策（fleet::PlanForceClearLink）+ 本地落地执行。
713	  // 决策规则集中在核心（零 ROS 依赖，可单测）：仅受理"受管清单内且当前离线"的车辆；
714	  // 锁归属必须经 mission->vehicle 绑定反查（严禁用"路径存档存在"之类的间接证据推断）。
715	  amr_dispatcher_core::fleet::ForceClearLinkRequest decision_req;
716	  decision_req.vehicle_id = req->vehicle_id;
717	  decision_req.confirm_vehicle_id = req->confirm_vehicle_id;
718	  decision_req.operator_id = req->operator_id;
719	  decision_req.reason = req->reason;
720	  decision_req.vehicle_in_managed_list =
721	      vda5050_links_.find(req->vehicle_id) != vda5050_links_.end();
722	  const auto link_it = vda5050_links_.find(req->vehicle_id);
723	  decision_req.vehicle_online = (link_it != vda5050_links_.end()) && link_it->second.online;
724	  decision_req.vehicle_quarantined =
725	      vda5050_quarantined_.find(req->vehicle_id) != vda5050_quarantined_.end();
726	  decision_req.mission_vehicle_bindings = vda5050_mission_vehicle_;
727	  if (reservation_table_) {
728	    for (const auto& [resource_id, owner] : reservation_table_->Snapshot()) {
729	      decision_req.held_locks[resource_id] = owner;
730	    }
731	  }
732	  const auto decision = amr_dispatcher_core::fleet::PlanForceClearLink(decision_req);
733	  if (!decision.allowed) {
734	    resp->success = false;
735	    resp->message = decision.reject_reason;
736	    return;
737	  }
738	
739	  // ---- 1) 释放该车名下锁（先于任务收口，保证 released_resources 可取证）----
740	  std::vector<std::string> released;
741	  if (reservation_table_) {
742	    for (const auto& [mission_id, ids] : decision.locks_by_mission) {
743	      const auto freed = reservation_table_->ReleaseResources(mission_id, ids);
744	      released.insert(released.end(), freed.begin(), freed.end());
745	    }
746	  }
747	  resp->released_resources.assign(released.begin(), released.end());
748	
749	  // ---- 2) 收口该车承接的在途任务 ----
750	  // 车辆已死，其承接的 mission 永远不会到达/完成，会一直占着 active_missions_ 与
751	  // 单车执行槽位，后续任务永远排不上（挂起守卫解除也派不出去）。
752	  // 人工强清 = 操作员宣告该任务作废：**全量释放 + 不重试 + 不回坞**，让队列立刻前进。
753	  // 不能走 FailMission：其恢复行为树可能判定 retry/dock（把死车任务重新入队），
754	  // 且资源释放取决于 BT 决策（可能保留锁），与"人工强解"语义相悖。
755	  for (const auto& mission_id : decision.missions_to_abort) {
756	    RCLCPP_WARN(get_logger(),
757	                "VDA 5050 force-clear: aborting in-flight mission %s bound to dead vehicle %s",
758	                mission_id.c_str(), req->vehicle_id.c_str());
759	    // 单车执行槽位释放 + 停车（否则槽位残留，后续任务永远无法派发）
760	    if (IsMissionTracked(mission_id)) {
761	      ReleaseTrackingSlot(mission_id);
762	      PublishStopPathForMission(mission_id);
763	    }
764	    {
765	      std::lock_guard<std::mutex> lock(active_missions_mutex_);
766	      active_missions_.erase(mission_id);
767	    }
768	    if (reservation_table_) {
769	      reservation_table_->Release(mission_id);  // 全量释放该任务名下锁
770	    }
771	    FinishExecuteGoal(mission_id, ExecuteFinish::kAbort,
772	                      "operator force-cleared offline VDA 5050 link", 1);
773	    mission_dispatch_time_.erase(mission_id);
774	    ForgetMissionDispatchState(mission_id);
775	    if (event_pub_ && event_pub_->is_activated()) {
776	      amr_dispatcher_interfaces::msg::MissionEvent msg;
777	      msg.stamp = now();
778	      msg.mission_id = mission_id;
779	      msg.event = "failed";
780	      msg.from_state = "ACTIVE";
781	      msg.to_state = "FAILED";
782	      msg.reason = "operator force-cleared offline VDA 5050 link for vehicle " + req->vehicle_id;
783	      event_pub_->publish(msg);
784	    }
785	  }
786	  ReArmQueueStartRequest();  // 队列后续任务需重新武装启动请求
787	
788	  // ---- 3) 车辆转入隔离态（**不摘除**受管清单）----
789	  // 评审 P0.5：通信失联不等于可以释放路权。强清后车辆仍然可见、可审计，
790	  // 但不再参与自动分配（选车时 quarantined -> 不合格），需显式恢复。
791	  vda5050_quarantined_.insert(req->vehicle_id);
792	  resp->quarantined = true;
793	
794	  // ---- 4) 审计与响应 ----
795	  resp->success = true;
796	  resp->message = "Force-cleared offline link for " + req->vehicle_id + ", released " +
797	                  std::to_string(released.size()) + " resource(s) | reason: " + req->reason +
798	                  " | operator: " + req->operator_id +
799	                  " | vehicle QUARANTINED (not auto-assignable until restored; physical "
800	                  "position NOT machine-verified — operator bears that risk)";
801	  RCLCPP_WARN(get_logger(),
802	              "VDA 5050 link %s FORCE-CLEARED by operator %s (reason=\"%s\", released %zu "
803	              "resource(s) [%s]) -> vehicle QUARANTINED; physical position NOT verified",
804	              req->vehicle_id.c_str(), req->operator_id.c_str(), req->reason.c_str(),
805	              released.size(),
806	              [&released]() {
807	                std::string joined;
808	                for (std::size_t i = 0; i < released.size(); ++i) {
809	                  if (i) joined += ",";
810	                  joined += released[i];
811	                }
812	                return joined;
813	              }()
814	                  .c_str());
815	}
