119	  // B3：交通协调模式（static = 现网行为；time_space = 时空窗预约）
120	  traffic_mode_ = get_parameter("traffic_mode").as_string();
121	  if (traffic_mode_ != "static" && traffic_mode_ != "time_space") {
122	    RCLCPP_ERROR(get_logger(),
123	                 "Invalid traffic_mode '%s' — falling back to 'static' (unknown mode is not "
124	                 "guessed)",
125	                 traffic_mode_.c_str());
126	    traffic_mode_ = "static";
127	  }
128	  time_space_timing_.cruise_speed_mps = get_parameter("time_space_cruise_speed_mps").as_double();
129	  time_space_timing_.accel_overhead_sec =
130	      get_parameter("time_space_accel_overhead_sec").as_double();
131	  time_space_timing_.turn_overhead_sec =
132	      get_parameter("time_space_turn_overhead_sec").as_double();
133	  time_space_timing_.safety_margin_m = get_parameter("time_space_safety_margin_m").as_double();
134	  time_space_timing_.min_headway_sec = get_parameter("time_space_min_headway_sec").as_double();
135	  RCLCPP_INFO(get_logger(), "Traffic coordination mode: %s", traffic_mode_.c_str());
136	
137	  // P0.6 / A6：选车上下文（静态目录 + 参数）
138	  required_capability_ = get_parameter("required_capability").as_string();
139	  min_battery_percent_ = get_parameter("min_battery_percent").as_double();
140	  vehicle_state_max_age_ms_ = get_parameter("vehicle_state_max_age_ms").as_int();
141	  LoadFleetCatalog();
142	
143	  submit_srv_ = create_service<amr_dispatcher_interfaces::srv::SubmitOrder>(
144	      "/dispatcher/submit_order",
145	      std::bind(&DispatcherNode::SubmitOrderCb, this, std::placeholders::_1, std::placeholders::_2));
146	  cancel_srv_ = create_service<amr_dispatcher_interfaces::srv::CancelOrder>(
147	      "/dispatcher/cancel_order",
148	      std::bind(&DispatcherNode::CancelOrderCb, this, std::placeholders::_1, std::placeholders::_2));
149	  pause_srv_ = create_service<amr_dispatcher_interfaces::srv::PauseMission>(
150	      "/dispatcher/pause_mission",
151	      std::bind(&DispatcherNode::PauseMissionCb, this, std::placeholders::_1, std::placeholders::_2));
152	  resume_srv_ = create_service<amr_dispatcher_interfaces::srv::ResumeMission>(
153	      "/dispatcher/resume_mission",
154	      std::bind(&DispatcherNode::ResumeMissionCb, this, std::placeholders::_1, std::placeholders::_2));
155	  reserve_srv_ = create_service<amr_dispatcher_interfaces::srv::ReserveResource>(
156	      "/dispatcher/reserve_resource",
157	      std::bind(&DispatcherNode::ReserveResourceCb, this, std::placeholders::_1, std::placeholders::_2));
158	  release_srv_ = create_service<amr_dispatcher_interfaces::srv::ReleaseResource>(
159	      "/dispatcher/release_resource",
160	      std::bind(&DispatcherNode::ReleaseResourceCb, this, std::placeholders::_1, std::placeholders::_2));
161	  force_clear_vda5050_link_srv_ =
162	      create_service<amr_dispatcher_interfaces::srv::ForceClearVda5050Link>(
163	          "/dispatcher/force_clear_vda5050_link",
164	          std::bind(&DispatcherNode::ForceClearVda5050LinkCb, this,
165	                    std::placeholders::_1, std::placeholders::_2));
166	  restore_vda5050_link_srv_ =
167	      create_service<amr_dispatcher_interfaces::srv::RestoreVda5050Link>(
168	          "/dispatcher/restore_vda5050_link",
169	          std::bind(&DispatcherNode::RestoreVda5050LinkCb, this,
170	                    std::placeholders::_1, std::placeholders::_2));
171	
172	  // 12 Core Services Registration
173	  enqueue_srv_ = create_service<amr_dispatcher_interfaces::srv::EnqueueMission>(
174	      "/v2/enqueue_mission",
175	      std::bind(&DispatcherNode::EnqueueMissionCb, this, std::placeholders::_1, std::placeholders::_2));
176	  cancel_queued_srv_ = create_service<amr_dispatcher_interfaces::srv::CancelQueuedMission>(
177	      "/v2/cancel_queued_mission",
178	      std::bind(&DispatcherNode::CancelQueuedMissionCb, this, std::placeholders::_1, std::placeholders::_2));
179	  preempt_srv_ = create_service<amr_dispatcher_interfaces::srv::PreemptMission>(
180	      "/v2/preempt_mission",
181	      std::bind(&DispatcherNode::PreemptMissionCb, this, std::placeholders::_1, std::placeholders::_2));
182	  reprioritize_srv_ = create_service<amr_dispatcher_interfaces::srv::ReprioritizeQueuedMission>(
183	      "/v2/reprioritize_queued_mission",
184	      std::bind(&DispatcherNode::ReprioritizeQueuedMissionCb, this, std::placeholders::_1, std::placeholders::_2));
185	  estimate_cost_srv_ = create_service<amr_dispatcher_interfaces::srv::EstimateMissionCost>(
186	      "/v2/estimate_mission_cost",
187	      std::bind(&DispatcherNode::EstimateMissionCostCb, this, std::placeholders::_1, std::placeholders::_2));
188	  block_route_srv_ = create_service<amr_dispatcher_interfaces::srv::BlockStationRoute>(
189	      "/v2/block_station_route",
190	      std::bind(&DispatcherNode::BlockStationRouteCb, this, std::placeholders::_1, std::placeholders::_2));
191	  detect_deadlock_srv_ = create_service<amr_dispatcher_interfaces::srv::DetectTrafficDeadlock>(
192	      "/v2/detect_traffic_deadlock",
193	      std::bind(&DispatcherNode::DetectTrafficDeadlockCb, this, std::placeholders::_1, std::placeholders::_2));
194	  list_stations_srv_ = create_service<amr_dispatcher_interfaces::srv::ListStations>(
195	      "/v2/list_stations",
196	      std::bind(&DispatcherNode::ListStationsCb, this, std::placeholders::_1, std::placeholders::_2));
197	  list_reservations_srv_ = create_service<amr_dispatcher_interfaces::srv::ListTrafficReservations>(
198	      "/v2/list_traffic_reservations",
199	      std::bind(&DispatcherNode::ListTrafficReservationsCb, this, std::placeholders::_1, std::placeholders::_2));
200	  reserve_facility_srv_ = create_service<amr_dispatcher_interfaces::srv::ReserveFacilityResource>(
201	      "/v2/reserve_facility_resource",
202	      std::bind(&DispatcherNode::ReserveFacilityResourceCb, this, std::placeholders::_1, std::placeholders::_2));
203	  snapshot_srv_ = create_service<amr_dispatcher_interfaces::srv::GetOperatorSnapshot>(
204	      "/v2/get_operator_snapshot",
205	      std::bind(&DispatcherNode::GetOperatorSnapshotCb, this, std::placeholders::_1, std::placeholders::_2));
206	  validate_site_srv_ = create_service<amr_dispatcher_interfaces::srv::ValidateSiteConfig>(
207	      "/v2/validate_site_config",
208	      std::bind(&DispatcherNode::ValidateSiteConfigCb, this, std::placeholders::_1, std::placeholders::_2));
209	
210	  // 导航后端：默认 plan（行为与既有代码逐字节一致）；action 模式派发改发 NavigateSequence 单点 goal
211	  navigation_backend_ = get_parameter("navigation_backend").as_string();
212	  if (navigation_backend_ != "plan" && navigation_backend_ != "action") {
213	    RCLCPP_WARN(get_logger(), "Unknown navigation_backend '%s', falling back to 'plan'",
214	                navigation_backend_.c_str());
215	    navigation_backend_ = "plan";
216	  }
217	  // ExecuteMission action server：HandleGoal 校验（非空/不重复/资源可预占），
218	  // HandleAccepted 只做入队 + 存 goal handle（不起线程）
219	  execute_action_server_ = rclcpp_action::create_server<ExecuteMission>(
220	      this, "/execute_mission",
221	      std::bind(&DispatcherNode::HandleGoal, this, std::placeholders::_1, std::placeholders::_2),
222	      std::bind(&DispatcherNode::HandleCancel, this, std::placeholders::_1),
223	      std::bind(&DispatcherNode::HandleAccepted, this, std::placeholders::_1));
224	  if (navigation_backend_ == "action") {
225	    nav_client_ = rclcpp_action::create_client<NavigateSequence>(this, "/navigate_sequence");
226	  }
227	
228	  // B6：参数热重载——比较器与三个调度节奏参数允许运行时改写。
229	  // 校验失败返回空 reason（rclcpp 按"拒绝"处理）；comparator 在此预校验，
230	  // 未知值直接拒绝（避免 SetComparator 对未知名静默失败导致实际策略与参数漂移）。
231	  param_callback_handle_ = add_on_set_parameters_callback(
232	      [this](const std::vector<rclcpp::Parameter>& params) {
233	        rcl_interfaces::msg::SetParametersResult result;
234	        result.successful = true;
235	        for (const auto& p : params) {
236	          const std::string& name = p.get_name();
237	          if (name == "comparator") {
238	            const std::string v = p.as_string();
239	            auto comp = amr_dispatcher_core::dispatcher::CreateMissionComparator(v);
240	            if (!comp) {
241	              result.successful = false;
242	              result.reason = "unknown comparator: " + v;
243	              RCLCPP_WARN(get_logger(), "Parameter reload rejected: %s",
244	                          result.reason.c_str());
245	              continue;
246	            }
247	            if (queue_) {
248	              queue_->SetComparator(std::move(comp));
249	            }
250	            RCLCPP_INFO(get_logger(), "Parameter reload: comparator -> %s", v.c_str());
251	          } else if (name == "schedule_rate_hz") {
252	            const double v = p.as_double();
253	            if (v <= 0.0) {
254	              result.successful = false;
255	              result.reason = "schedule_rate_hz must be > 0";
256	              continue;
257	            }
258	            if (schedule_timer_) {
259	              schedule_timer_->reset();
260	              schedule_timer_ = create_wall_timer(
261	                  std::chrono::duration<double>(1.0 / v),
262	                  std::bind(&DispatcherNode::ScheduleTick, this));
263	            }
264	            RCLCPP_INFO(get_logger(), "Parameter reload: schedule_rate_hz -> %.2f", v);
265	          } else if (name == "deadlock_check_rate_hz") {
266	            const double v = p.as_double();
267	            if (v <= 0.0) {
268	              result.successful = false;
269	              result.reason = "deadlock_check_rate_hz must be > 0";
270	              continue;
271	            }
272	            if (deadlock_timer_) {
273	              deadlock_timer_->reset();
274	              deadlock_timer_ = create_wall_timer(
275	                  std::chrono::duration<double>(1.0 / v),
276	                  std::bind(&DispatcherNode::DeadlockTick, this));
277	            }
278	            RCLCPP_INFO(get_logger(), "Parameter reload: deadlock_check_rate_hz -> %.2f", v);
279	          } else if (name == "max_active_missions") {
280	            const int64_t v = p.as_int();
281	            if (v < 1) {
282	              result.successful = false;
283	              result.reason = "max_active_missions must be >= 1";
284	              continue;
285	            }
286	            RCLCPP_INFO(get_logger(), "Parameter reload: max_active_missions -> %lld",
287	                        static_cast<long long>(v));
288	          } else if (name == "planner_type") {
289	            const std::string v = p.as_string();
290	            if (v != "mock" && v != "skeleton") {
291	              result.successful = false;
292	              result.reason = "planner_type must be 'mock' or 'skeleton': " + v;
293	              RCLCPP_WARN(get_logger(), "Parameter reload rejected: %s",
294	                          result.reason.c_str());
295	              continue;
296	            }
297	            planner_type_ = v;
298	            RebuildPlanner();  // 单线程 spin：回调期间无规划请求在途，可安全换实例
299	            RCLCPP_INFO(get_logger(), "Parameter reload: planner_type -> %s", v.c_str());
300	          } else if (name == "expected_map_hash") {
301	            expected_map_hash_ = p.as_string();
302	            RCLCPP_INFO(get_logger(),
303	                        "Parameter reload: expected_map_hash -> %s",
304	                        expected_map_hash_.empty() ? "<disabled>"
305	                                                   : expected_map_hash_.c_str());
306	          }
307	          // 其余已声明参数不回执：rclcpp 仍正常赋值，仅不产生日志噪声
308	        }
309	        return result;
310	      });
311	
312	  RCLCPP_INFO(get_logger(),
313	              "DispatcherNode configured (capacity=%zu, comparator=%s, navigation_backend=%s)",
314	              cap, comp_name.c_str(), navigation_backend_.c_str());
315	  return CallbackReturn::SUCCESS;
316	}
