318	CallbackReturn DispatcherNode::on_activate(const rclcpp_lifecycle::State& /*state*/) {
319	  state_pub_->on_activate();
320	  event_pub_->on_activate();
321	  plan_pub_->on_activate();
322	  topology_pub_->on_activate();
323	  for (auto& [vehicle_id, pub] : vda5050_order_pubs_) {
324	    pub->on_activate();  // Task 6：send_order 发布端随节点激活（未激活则 publish 为空操作）
325	  }
326	  for (auto& [vehicle_id, pub] : vehicle_plan_pubs_) {
327	    pub->on_activate();  // P0.6：per-vehicle 计划发布端随节点激活
328	  }
329	
330	  const double sched_hz = get_parameter("schedule_rate_hz").as_double();
331	  schedule_timer_ = create_wall_timer(
332	      std::chrono::duration<double>(1.0 / sched_hz),
333	      std::bind(&DispatcherNode::ScheduleTick, this));
334	
335	  const double deadlock_hz = get_parameter("deadlock_check_rate_hz").as_double();
336	  deadlock_timer_ = create_wall_timer(
337	      std::chrono::duration<double>(1.0 / deadlock_hz),
338	      std::bind(&DispatcherNode::DeadlockTick, this));
339	
340	  state_timer_ = create_wall_timer(500ms, std::bind(&DispatcherNode::PublishState, this));
341	
342	  // 1Hz 驱动站点目录 mtime 热重载（HotReloadWatcher 由调用方驱动）
343	  reload_timer_ = create_wall_timer(1s, [this]() {
344	    if (!catalog_reloader_) return;
345	    if (catalog_reloader_->Tick()) {
346	      RCLCPP_INFO(get_logger(), "Station catalog hot-reloaded: %zu stations",
347	                  catalog_reloader_->catalog().stations.size());
348	      // SkeletonPlanner 持有目录副本：热重载后必须同步，否则仍按旧折线规划
349	      auto* skeleton_planner =
350	          dynamic_cast<amr_dispatcher_core::planning::SkeletonPlanner*>(planner_.get());
351	      if (skeleton_planner != nullptr) {
352	        skeleton_planner->UpdateCatalog(catalog_reloader_->catalog());
353	        RCLCPP_INFO(get_logger(), "SkeletonPlanner catalog synchronized (%zu stations)",
354	                    catalog_reloader_->catalog().stations.size());
355	      }
356	    } else if (!catalog_reloader_->last_error().empty()) {
357	      // 重载失败（YAML 解析或校验不过）：旧目录继续生效，节流告警提示修复文件
358	      RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 10000,
359	                           "Station catalog reload failed, keeping previous: %s",
360	                           catalog_reloader_->last_error().c_str());
361	    }
362	  });
363	
364	  RCLCPP_INFO(get_logger(), "DispatcherNode activated");
365	  return CallbackReturn::SUCCESS;
366	}
