368	void DispatcherNode::RebuildPlanner() {
369	  const double step_size = get_parameter("path_step_size_m").as_double();
370	  if (planner_type_ == "skeleton") {
371	    planner_ = std::make_unique<amr_dispatcher_core::planning::SkeletonPlanner>(
372	        catalog_reloader_ ? catalog_reloader_->catalog()
373	                          : amr_dispatcher_core::catalog::StationCatalog{},
374	        amr_dispatcher_core::planning::SkeletonPlanner::Config{step_size});

