  // B5：真实现——mission_file 作为站点对编码（"from->to" 或 "from:to"），
  // 用 StationCatalog 直线距离和喂 EstimateDistanceCost；电池参数无 srv 字段，
  // 沿用核心测试约定（0.1 V/m，最低 21.0 V 与 charging workflow 阈值一致）。
  resp->mission_id = req->mission_file;

