1380	void DispatcherNode::FinishExecuteGoal(const std::string& mission_id, ExecuteFinish kind,
1381	                                        const std::string& message, std::int32_t error_code) {
1382	  auto it = execute_goal_handles_.find(mission_id);
1383	  if (it == execute_goal_handles_.end()) {
1384	    return;
1385	  }
1386	  auto handle = it->second;
1387	  execute_goal_handles_.erase(it);
