1393	  if (dispatch_time != mission_dispatch_time_.end()) {
1394	    duration_sec = std::chrono::duration<double>(
1395	                       std::chrono::steady_clock::now() - dispatch_time->second)
1396	                       .count();
1397	    mission_dispatch_time_.erase(dispatch_time);
1398	  }
1399	  if (!handle || !handle->is_active()) {
1400	    return;
1401	  }
1402	
1403	  auto result = std::make_shared<ExecuteMission::Result>();
1404	  result->success = (kind == ExecuteFinish::kSucceed);
1405	  result->error_code = error_code;
1406	  result->message = message;
1407	  result->total_duration_sec = duration_sec;
