408	CallbackReturn DispatcherNode::on_cleanup(const rclcpp_lifecycle::State& /*state*/) {
409	  submit_srv_.reset();
410	  cancel_srv_.reset();
411	  pause_srv_.reset();
412	  resume_srv_.reset();
413	  reserve_srv_.reset();
414	  release_srv_.reset();
415	  force_clear_vda5050_link_srv_.reset();
416	  restore_vda5050_link_srv_.reset();
417	  enqueue_srv_.reset();
418	  cancel_queued_srv_.reset();
419	  preempt_srv_.reset();
420	  reprioritize_srv_.reset();
421	  estimate_cost_srv_.reset();
422	  block_route_srv_.reset();
423	  detect_deadlock_srv_.reset();
424	  list_stations_srv_.reset();
425	  list_reservations_srv_.reset();
426	  reserve_facility_srv_.reset();
427	  snapshot_srv_.reset();
428	  validate_site_srv_.reset();
429	  // B2：clean up 前先逐个收口在途 ExecuteMission goal——
430	  // 不复位的 handle 在 server 销毁后会让 action 客户端永久悬挂；
431	  // 同时释放 HandleGoal 阶段预占的 required_resources 锁。
432	  // rclcpp_action 状态机约束：canceled() 仅 CANCELING、abort() 仅 EXECUTING，
433	  // 其余状态（ACCEPTED 未执行）先 execute() 再 abort()，与 FinishExecuteGoal 同构。
434	  for (auto& [mission_id, handle] : execute_goal_handles_) {
435	    if (!handle) {
436	      continue;
437	    }
438	    if (reservation_table_) {
439	      reservation_table_->Release(mission_id);
440	    }
441	    auto result = std::make_shared<ExecuteMission::Result>();
442	    result->success = false;
443	    result->error_code = 1;
444	    result->message = "dispatcher cleaning up";
445	    try {
446	      if (handle->is_canceling()) {
447	        handle->canceled(result);
448	      } else if (handle->is_executing()) {
449	        handle->abort(result);
450	      } else {
451	        handle->execute();
452	        handle->abort(result);
453	      }
454	    } catch (const std::exception& ex) {
455	      RCLCPP_ERROR(get_logger(), "on_cleanup: finish goal %s failed: %s",
456	                   mission_id.c_str(), ex.what());
457	    }
