 7	// P0.6 多车并发的「话题与 TF 隔离」命名契约（A4）。
 8	//
 9	// 兼容性红线（不可破）：vehicle_id 为空（默认）时，本文件解析出的每一个话题名
10	// 都必须与改动前**逐字一致**（/plan、/cmd_vel_raw、/cmd_vel_safe、/odom、
11	// /tracking/error、/safety/heartbeat/*、/safety/estop、/safety/bumper、
12	// /safety/manual_takeover、/chassis/link_health、/safety/state）。
13	//
14	// 派生规则（统一形状，suffix 拼接）：
15	//   有效名 = 显式覆盖参数 非空 ? 显式覆盖参数
16	//                              : (vehicle_id 非空 ? legacy_name + "/" + vehicle_id
17	//                                                 : legacy_name)
18	// 例：legacy "/plan" + vid "amr_01" -> "/plan/amr_01"
19	//     legacy "/safety/heartbeat/path_tracker" + vid "amr_01"
20	//                                  -> "/safety/heartbeat/path_tracker/amr_01"
21	namespace amr_dispatcher_ros {
22	
23	// vehicle_id 必须符合 ROS 2 名称规范 [A-Za-z_][A-Za-z0-9_]*
24	// （外部来源的 id，如 VDA 5050 serialNumber，不保证合法）。
25	inline bool IsValidVehicleId(const std::string& vehicle_id) {
26	  if (vehicle_id.empty()) {
27	    return false;
28	  }
29	  const char first = vehicle_id.front();
30	  const bool first_ok = (first >= 'A' && first <= 'Z') || (first >= 'a' && first <= 'z') ||
31	                        first == '_';
32	  if (!first_ok) {
33	    return false;
34	  }
35	  for (const char c : vehicle_id) {
36	    const bool ok = (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') ||
37	                    (c >= '0' && c <= '9') || c == '_';
38	    if (!ok) {
39	      return false;
40	    }
41	  }
42	  return true;
43	}
44	
45	// 话题名解析：显式覆盖 > per-vehicle 派生 > legacy 全局名（单车兼容红线）。
46	inline std::string ResolveVehicleTopic(const std::string& override_topic,
47	                                       const std::string& legacy_topic,
48	                                       const std::string& vehicle_id) {
49	  if (!override_topic.empty()) {
50	    return override_topic;
51	  }
52	  if (vehicle_id.empty()) {
53	    return legacy_topic;
54	  }
55	  return legacy_topic + "/" + vehicle_id;
56	}
57	
58	// 逗号分隔 vehicle id 列表解析：裁剪空白、保序去重。
59	inline std::vector<std::string> SplitVehicleIds(const std::string& csv) {
60	  std::vector<std::string> out;
61	  std::size_t start = 0;
62	  while (start <= csv.size()) {
63	    const std::size_t end = csv.find(',', start);
64	    const std::string raw = csv.substr(
65	        start, end == std::string::npos ? std::string::npos : end - start);
66	    std::string token;
67	    for (const char c : raw) {
68	      if (c == ' ' || c == '\t' || c == '\n' || c == '\r') {
69	        continue;
70	      }
71	      token.push_back(c);
72	    }
73	    if (!token.empty()) {
74	      bool seen = false;
75	      for (const auto& existing : out) {
76	        if (existing == token) {
77	          seen = true;
78	          break;
79	        }
80	      }
81	      if (!seen) {
82	        out.push_back(token);
83	      }
84	    }
85	    if (end == std::string::npos) {
86	      break;
87	    }
88	    start = end + 1;
89	  }
90	  return out;
91	}
92	
93	}  // namespace amr_dispatcher_ros

