void DispatcherNode::TrackingErrorCbForVehicle(
    const std::string& vehicle_id, const amr_dispatcher_interfaces::msg::TrackingError::SharedPtr msg) {
  // A5 收口点：把 arrived 信号路由到"该车正在执行的任务"并完成它。
